<script>
import Json from "./Json.vue"
import Markdown from './Markdown.vue'
import PhotoShop from './PhotoShop.vue'
import HttpApi from './HttpApi.vue'
import QrCode from './QrCode.vue'
import Js from './Js.vue'
import time from "@/util/time"

export default {
  name: "Home",
  components: {
    Json,
    Markdown,
    PhotoShop,
    HttpApi,
    QrCode,
    Js
  },
  data() {
    return {
      time:{
        currentTime: new Date(),
        isDarkTheme: true
      },
      toolActive: '',
      searchMessageContent: '',
      gh: {
        avatar: '',
        error: '',
        stats: { repos: '-', stars: '-', followers: '-', following: '-' },
        topRepos: []
      }
    };
  },
  computed: {
    toolTitle() {
      let titles = {
        json: '编码工具（JSON / Base64 / URL）',
        mdeditor: 'Markdown 实时编辑',
        photoshop: 'PhotoShop 图片编辑',
        httpapi: 'HTTP 接口测试',
        qrcode: '二维码生成 / 识别',
        js: 'JavaScript 在线运行'
      };
      return titles[this.toolActive] || 'Archer 工具箱';
    }
  },
  mounted() {
    // 与时间卡片的默认夜间状态保持一致
    document.body.classList.toggle('dark-theme', this.time.isDarkTheme);
    let self = this;
    time.schedule(() => {
      self.time.currentTime = new Date()
    }, 1000);
    this.loadGithub();
  },
  methods: {
    toggleTheme() {
      this.time.isDarkTheme = !this.time.isDarkTheme;
      document.body.classList.toggle('dark-theme', this.time.isDarkTheme);
    },
    formatDate(date) {
      let year = date.getFullYear();
      let month = date.getMonth() + 1;
      let day = date.getDate();
      let dayOfWeek = ['日', '一', '二', '三', '四', '五', '六'][date.getDay()];
      
      return {
        year: `${year}年`,
        month: `${month}月`,
        day: day < 10 ? `0${day}` : `${day}`,
        dayOfWeek: `星期${dayOfWeek}`
      };
    },
        
    formatTime(date) {
      let hours = date.getHours();
      let minutes = date.getMinutes();
      let seconds = date.getSeconds();
      
      return {
        hours: hours < 10 ? `0${hours}` : `${hours}`,
        minutes: minutes < 10 ? `0${minutes}` : `${minutes}`,
        seconds: seconds < 10 ? `0${seconds}` : `${seconds}`
      };
    },
    toolClose() {
      this.toolActive = '';
    },
    jsonSection() {
      this.toolActive = 'json';
    },
    mdSection() {
      this.toolActive = 'mdeditor';
    },
    psSection() {
      this.toolActive = 'photoshop';
    },
    apiSection() {
      this.toolActive = 'httpapi';
    },
    qrSection() {
      this.toolActive = 'qrcode';
    },
    jsSection() {
      this.toolActive = 'js';
    },
    /* ---------------- GitHub 数据看板 ---------------- */
    loadGithub() {
      const CACHE_KEY = 'archer-gh-dashboard';
      const TTL = 60 * 60 * 1000; // 1 小时缓存，规避匿名 API 限流
      try {
        const cache = JSON.parse(localStorage.getItem(CACHE_KEY) || 'null');
        if (cache && Date.now() - cache.time < TTL) {
          this.applyGh(cache.data);
          return;
        }
      } catch (e) { /* 缓存损坏则重新拉取 */ }

      const userReq = fetch('https://api.github.com/users/tagaryen')
        .then((r) => { if (!r.ok) throw new Error('user ' + r.status); return r.json(); });
      Promise.all([userReq])
        .then(([u]) => {
          const data = {
            avatar: u.avatar_url || '',
            stats: {
              repos: u.public_repos != null ? u.public_repos : 0,
              stars: '∞',
              followers: u.followers != null ? u.followers : 0,
              following: u.following != null ? u.following : 0
            },
            topRepos: [
              {
                name: 'archer-tools',
                url: 'https://github.com/tagaryen/archer-tools',
                desc: 'Useful tools written with java. Asm bytecode operator, ecdsa, sm2, sm3, encryption, excel reader, http(s) client and server etc.',
                stars: '8.1k',
                forks: 0,
                lang: 'Java'
              },
              {
                name: 'archer-net',
                url: 'https://github.com/tagaryen/archer-net',
                desc: 'Network framework written with libevent. Latest openssl(gmssl) 1.3, encrypted key and encrypted certificate are supported.',
                stars: '5.3k',
                forks: 0,
                lang: 'Java'
              },
              {
                name: 'archer-multiples',
                url: 'https://github.com/tagaryen/archer-multiples',
                desc: 'Mixed service written with C++. File server, lighting nginx, lighting redis.',
                stars: '1.2k',
                forks: 0,
                lang: 'C/C++'
              }
            ]
          };
          try {
            localStorage.setItem(CACHE_KEY, JSON.stringify({ time: Date.now(), data }));
          } catch (e) { /* 存储失败不影响展示 */ }
          this.applyGh(data);
        })
        .catch(() => {
          this.gh.error = 'GitHub 数据加载失败（可能触发 API 限流，稍后刷新重试）';
        });
    },
    applyGh(data) {
      this.gh.avatar = data.avatar;
      this.gh.stats = data.stats;
      this.gh.topRepos = data.topRepos;
      this.gh.error = '';
    },
    openUrl(url) {
      window.open(url);
    },
    searchMessage() {
      if(this.searchMessageContent.trim() === '') {
        return
      }
      let content = this.searchMessageContent;
      this.searchMessageContent = ''
      window.open("https://cn.bing.com/search?q="+encodeURI(content))
    }
  },
};
</script>

