<template>
  <div class="Markdown">
    <!-- 头部：标题 + 视图切换 + 导出 PDF -->
    <div class="md-header">
      <div class="md-title">
        <span class="md-title-icon">
          <svg viewBox="0 0 24 24">
            <path
              d="M20.56 18H3.44C2.65 18 2 17.37 2 16.59V7.41C2 6.63 2.65 6 3.44 6H20.56C21.35 6 22 6.63 22 7.41V16.59C22 17.37 21.35 18 20.56 18M6.81 15.19V11.53L8.73 13.88L10.65 11.53V15.19H12.58V8.81H10.65L8.73 11.16L6.81 8.81H4.89V15.19H6.81M19.69 12L17.06 9.19V11.06H14.19V12.94H17.06V14.81L19.69 12Z"
            />
          </svg>
        </span>
        <h4>Markdown</h4>
        <span class="md-autosave">
          <span class="md-dot"></span>内容自动保存
        </span>
      </div>
      <div class="md-actions">
        <!-- 视图模式：编辑 / 分屏 / 预览 -->
        <div class="md-switch">
          <button
            v-for="v in views"
            :key="v.key"
            :class="{ active: view === v.key }"
            @click="setView(v.key)"
          >
            <svg viewBox="0 0 24 24"><path :d="v.icon" /></svg>{{ v.label }}
          </button>
        </div>
      </div>
    </div>

    <!-- 主体：编辑 / 分屏 用 Editor，纯预览用 Viewer -->
    <div class="md-body" :class="'view-' + view">
      <Editor
        v-if="view !== 'preview'"
        class="md-editor"
        ref="editor"
        mode="split"
        :value="value"
        :plugins="plugins"
        @change="handleChange"
      />
      <div v-else class="md-preview">
        <Viewer :value="value" :plugins="plugins" />
      </div>
    </div>
  </div>
</template>

<script>
import "bytemd/dist/index.min.css";
import { Editor, Viewer } from "@bytemd/vue";
import codeCopy from "@/util/mdcopypl";
import gfm from "@bytemd/plugin-gfm";

const plugins = [codeCopy(), gfm()];
const VIEW_KEY = "markdown-view-mode";
const MD_KEY = "markdown-text";

export default {
  name: "Markdown",
  components: { Editor, Viewer },
  data() {
    // 沿用原 MdEditor 的 localStorage key，已保存内容无缝迁移
    let md = window.localStorage.getItem(MD_KEY);
    if (!md) {
      md = "# 在此处编辑";
    }
    return {
      value: md,
      plugins: plugins,
      view: "split",
      views: [
        {
          key: "edit",
          label: "编辑",
          icon: "M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z",
        },
        {
          key: "split",
          label: "分屏",
          icon: "M10 18h5V5h-5v13zm-6 0h5V5H4v13zM16 5v13h5V5h-5z",
        },
        {
          key: "preview",
          label: "预览",
          icon: "M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z",
        },
      ],
    };
  },
  mounted() {
    const v = window.localStorage.getItem(VIEW_KEY);
    if (v === "edit" || v === "split" || v === "preview") {
      this.view = v;
    }
  },
  methods: {
    handleChange(v) {
      this.value = v;
      window.localStorage.setItem(MD_KEY, v);
    },
    setView(v) {
      this.view = v;
      window.localStorage.setItem(VIEW_KEY, v);
    },
  },
};
</script>

