<template>
  <div class="js-runner tool-panel">
    <div class="js-toolbar">
      <span class="js-title">JavaScript 在线运行</span>
      <div class="js-actions">
        <button class="js-btn js-btn-run" @click="run" title="运行代码 (Ctrl+Enter)">▶ 运行</button>
        <button class="js-btn" @click="loadExample">示例</button>
        <button class="js-btn" @click="clearCode">清空代码</button>
        <button class="js-btn" @click="clearOutput">清空输出</button>
        <button class="js-btn" :disabled="!logs.length" @click="copyOutput">复制输出</button>
      </div>
    </div>
    <div class="js-main">
      <textarea
        class="js-editor"
        v-model="code"
        spellcheck="false"
        placeholder="在此输入 JavaScript 代码，支持 console.log / 返回值 / async-await…"
        @keydown.ctrl.enter.exact.prevent="run"
      ></textarea>
      <div class="js-output">
        <div class="js-output-empty" v-if="!logs.length">暂无输出，点击「运行」或按 Ctrl+Enter 执行代码</div>
        <div v-for="(log, i) in logs" :key="i" :class="['js-log', 'js-log-' + log.type]">
          <span class="js-log-tag">{{ log.type }}</span>
          <pre class="js-log-text">{{ log.text }}</pre>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "JsRunner",
  data() {
    return {
      code: "",
      logs: []
    };
  },
  methods: {
    /* 任意值转可读字符串，处理循环引用 / BigInt / 函数 / Error */
    formatValue(v) {
      if (typeof v === "string") return v;
      if (typeof v === "function") return v.toString();
      if (typeof v === "bigint") return v.toString() + "n";
      if (v instanceof Error) return v.stack || v.message;
      if (v === undefined) return "undefined";
      try {
        const seen = new Set();
        const text = JSON.stringify(v, (key, val) => {
          if (typeof val === "bigint") return val.toString() + "n";
          if (typeof val === "function") return val.toString();
          if (val instanceof Error) return val.stack || String(val);
          if (typeof val === "object" && val !== null) {
            if (seen.has(val)) return "[Circular]";
            seen.add(val);
          }
          return val;
        }, 2);
        return text === undefined ? String(v) : text;
      } catch (e) {
        return String(v);
      }
    },
    run() {
      const logs = [];
      this.logs = logs;
      const self = this;
      // 劫持 console，把输出收集到面板
      const sandboxConsole = {};
      ["log", "info", "warn", "error", "debug"].forEach((level) => {
        sandboxConsole[level] = (...args) => {
          logs.push({
            type: level === "debug" ? "log" : level,
            text: args.map((a) => self.formatValue(a)).join(" ")
          });
        };
      });
      try {
        const fn = new Function("console", '"use strict";\n' + this.code);
        const ret = fn(sandboxConsole);
        if (ret && typeof ret.then === "function") {
          // 异步代码：等待 Promise 结果
          logs.push({ type: "info", text: "[Promise] 等待异步结果…" });
          ret
            .then((v) => {
              if (v !== undefined) logs.push({ type: "return", text: self.formatValue(v) });
            })
            .catch((e) => {
              logs.push({ type: "error", text: "Uncaught (in promise) " + self.formatValue(e) });
            });
        } else if (ret !== undefined) {
          logs.push({ type: "return", text: self.formatValue(ret) });
        }
        if (!logs.length) {
          logs.push({ type: "info", text: "代码已执行，无输出（可使用 console.log 打印结果）" });
        }
      } catch (e) {
        logs.push({ type: "error", text: String((e && e.stack) || e) });
      }
    },
    loadExample() {
      this.code = [
        "// 快速排序示例",
        "function quickSort(arr) {",
        "  if (arr.length <= 1) return arr;",
        "  const [pivot, ...rest] = arr;",
        "  return [",
        "    ...quickSort(rest.filter(x => x < pivot)),",
        "    pivot,",
        "    ...quickSort(rest.filter(x => x >= pivot))",
        "  ];",
        "}",
        "const data = [3, 6, 1, 8, 2, 9, 4];",
        "console.log('排序前:', data);",
        "console.log('排序后:', quickSort(data));",
        "console.warn('这是一条警告');",
        "return { 总数: data.length, 最大值: Math.max(...data) };"
      ].join("\n");
    },
    clearCode() {
      this.code = "";
    },
    clearOutput() {
      this.logs = [];
    },
    copyOutput() {
      const text = this.logs.map((l) => "[" + l.type + "] " + l.text).join("\n");
      navigator.clipboard
        .writeText(text)
        .then(() => this.$message.success("输出已复制"))
        .catch(() => this.$message.error("复制失败，请手动复制"));
    }
  }
};
</script>

