<template>
  <div class="QrCode">
    <!-- 功能 Tab：生成 / 识别 -->
    <div class="qr-tabs">
      <span :class="['qr-tab', { active: tab === 'gen' }]" @click="tab = 'gen'">生成二维码</span>
      <span :class="['qr-tab', { active: tab === 'scan' }]" @click="tab = 'scan'">识别二维码</span>
    </div>

    <!-- ============ 生成 ============ -->
    <div class="qr-panel" v-if="tab === 'gen'">
      <div class="qr-input-block">
        <div class="qr-block-title">内容</div>
        <textarea v-model="qrText" spellcheck="false" placeholder="输入文本、链接等内容，实时生成二维码"></textarea>
      </div>
      <div class="qr-actions">
        <label class="qr-size-label">
          尺寸
          <select v-model.number="qrSize" class="qr-size-select">
            <option :value="128">128px</option>
            <option :value="256">256px</option>
            <option :value="512">512px</option>
          </select>
        </label>
        <div :class="['qr-btn', 'qr-btn-primary', { 'qr-btn-disabled': !qrDataUrl }]" @click="downloadQr">
          下载 PNG
        </div>
      </div>
      <div class="qr-preview">
        <img v-if="qrDataUrl" :src="qrDataUrl" :style="{ width: previewSize + 'px', height: previewSize + 'px' }" alt="二维码" />
        <div v-else class="qr-empty">输入内容后自动生成</div>
      </div>
    </div>

    <!-- ============ 识别 ============ -->
    <div class="qr-panel" v-else>
      <div
        class="qr-dropzone"
        tabindex="0"
        @click="$refs.qrFile.click()"
        @dragover.prevent
        @drop.prevent="onDrop"
        @paste="onPaste"
      >
        <input ref="qrFile" type="file" accept="image/*" style="display: none" @change="onFileChange" />
        <template v-if="!scanImg">
          <div class="qr-drop-icon">+</div>
          <div>点击选择图片，或拖拽 / 粘贴图片到此处</div>
        </template>
        <img v-else :src="scanImg" class="qr-scan-img" alt="待识别图片" />
      </div>
      <div class="qr-actions" v-if="scanImg">
        <div class="qr-btn" @click="resetScan">重新选择</div>
        <div class="qr-btn" :class="{ 'qr-btn-disabled': !scanResult }" @click="copyResult">复制结果</div>
      </div>
      <div class="qr-result" v-if="scanResult || scanError">
        <div class="qr-block-title">识别结果</div>
        <div v-if="scanResult" class="qr-result-text">{{ scanResult }}</div>
        <div v-else class="qr-result-error">{{ scanError }}</div>
      </div>
    </div>
  </div>
</template>

<script>
import QRCode from "qrcode";
import jsQR from "jsqr";

export default {
  name: "QrCode",
  data() {
    return {
      tab: "gen",
      qrText: "",
      qrSize: 256,
      qrDataUrl: "",
      scanImg: "",
      scanResult: "",
      scanError: "",
      _genTimer: null,
    };
  },
  computed: {
    // 预览区限制展示大小，不影响下载分辨率
    previewSize() {
      return Math.min(this.qrSize, 260);
    },
  },
  watch: {
    qrText() {
      this.scheduleGenerate();
    },
    qrSize() {
      this.scheduleGenerate();
    },
  },
  methods: {
    /* ---------------- 生成 ---------------- */
    scheduleGenerate() {
      clearTimeout(this._genTimer);
      this._genTimer = setTimeout(() => this.generate(), 250);
    },
    generate() {
      if (!this.qrText) {
        this.qrDataUrl = "";
        return;
      }
      QRCode.toDataURL(this.qrText, {
        width: this.qrSize,
        margin: 2,
        color: { dark: "#1f2430", light: "#ffffff" },
      })
        .then((url) => {
          this.qrDataUrl = url;
        })
        .catch(() => {
          this.qrDataUrl = "";
          this.$message.warning("内容过长或包含非法字符，无法生成二维码");
        });
    },
    downloadQr() {
      if (!this.qrDataUrl) return;
      const a = document.createElement("a");
      a.href = this.qrDataUrl;
      a.download = "qrcode.png";
      a.click();
    },
    /* ---------------- 识别 ---------------- */
    onFileChange(e) {
      const file = e.target.files && e.target.files[0];
      if (file) this.decodeFile(file);
      e.target.value = "";
    },
    onDrop(e) {
      const file = e.dataTransfer.files && e.dataTransfer.files[0];
      if (file && file.type.startsWith("image/")) {
        this.decodeFile(file);
      }
    },
    onPaste(e) {
      const items = e.clipboardData && e.clipboardData.items;
      if (!items) return;
      for (const item of items) {
        if (item.type.startsWith("image/")) {
          this.decodeFile(item.getAsFile());
          break;
        }
      }
    },
    decodeFile(file) {
      const reader = new FileReader();
      reader.onload = () => {
        const img = new Image();
        img.onload = () => {
          this.scanImg = reader.result;
          const canvas = document.createElement("canvas");
          canvas.width = img.naturalWidth;
          canvas.height = img.naturalHeight;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, canvas.width, canvas.height);
          this.scanResult = code ? code.data : "";
          this.scanError = code ? "" : "未能识别到二维码，请换一张更清晰的图片";
        };
        img.src = reader.result;
      };
      reader.readAsDataURL(file);
    },
    resetScan() {
      this.scanImg = "";
      this.scanResult = "";
      this.scanError = "";
    },
    copyResult() {
      if (!this.scanResult) return;
      const done = () => this.$message.success("已复制");
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(this.scanResult).then(done, () => this.$message.error("复制失败"));
      } else {
        const ta = document.createElement("textarea");
        ta.value = this.scanResult;
        document.body.appendChild(ta);
        ta.select();
        try {
          document.execCommand("copy");
          done();
        } catch (e) {
          this.$message.error("复制失败");
        }
        document.body.removeChild(ta);
      }
    },
  },
};
</script>

