<template>
  <div class="Json">
    <!-- 功能 Tab：JSON / Base64 / URL -->
    <div class="codec-tabs">
      <span :class="['codec-tab', { active: tab === 'json' }]" @click="tab = 'json'">JSON</span>
      <span :class="['codec-tab', { active: tab === 'base64' }]" @click="tab = 'base64'">Base64</span>
      <span :class="['codec-tab', { active: tab === 'url' }]" @click="tab = 'url'">URL 编解码</span>
    </div>

    <template v-if="tab === 'json'">
      <div class="json-head-bar">
      <div class="json-head-actions">
        <div class="json-head-btn json-btn-primary" @click="jsonFormat">
          <svg class="json-btn-icon" viewBox="0 0 24 24" aria-hidden="true">
            <path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
              d="M4 6h6m-6 6h10m-10 6h4M18 6v12m0 0-3-3m3 3 3-3" />
          </svg>
          <span>格式化</span>
        </div>
        <div class="json-head-btn" @click="jsonStringify">
          <svg class="json-btn-icon" viewBox="0 0 24 24" aria-hidden="true">
            <path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
              d="M4 12h16M8 7l4 5-4 5m8-10 4 5-4 5" />
          </svg>
          <span>压缩</span>
        </div>
      </div>

      <div class="json-head-title">
        <span class="json-head-badge">{{ jsonLength }} 字符</span>
      </div>

      <div class="json-head-actions json-head-actions-right">
        <div class="json-head-btn" @click="copyJson">
