        <div class="json-editor-tip">
          <span>格式化：美化缩进 4 空格</span>
          <span>压缩：移除全部空白</span>
        </div>
      </div>
    </div>
    </template>

    <!-- Base64 编解码 -->
    <div class="codec-panel" v-else-if="tab === 'base64'">
      <div class="codec-block">
        <div class="codec-block-title">原文</div>
        <textarea v-model="base64Input" spellcheck="false" placeholder="输入要编码的文本（支持中文）"></textarea>
      </div>
      <div class="codec-actions">
        <div class="codec-btn codec-btn-primary" @click="base64Encode">编码 ↓</div>
        <div class="codec-btn" @click="base64Decode">解码 ↑</div>
        <div class="codec-btn" @click="copyCodec(base64Output)">复制结果</div>
        <div class="codec-btn codec-btn-danger" @click="base64Input = ''; base64Output = ''">清空</div>
      </div>
      <div class="codec-block">
        <div class="codec-block-title">Base64</div>
        <textarea v-model="base64Output" spellcheck="false" placeholder="编码结果 / 在此粘贴 Base64 进行解码"></textarea>
      </div>
    </div>

    <!-- URL 编解码 -->
    <div class="codec-panel" v-else-if="tab === 'url'">
      <div class="codec-block">
        <div class="codec-block-title">原文</div>
        <textarea v-model="urlInput" spellcheck="false" placeholder="输入要编码的文本或参数"></textarea>
      </div>
      <div class="codec-actions">
        <div class="codec-btn codec-btn-primary" @click="urlEncode">编码 ↓</div>
        <div class="codec-btn" @click="urlDecode">解码 ↑</div>
        <div class="codec-btn" @click="copyCodec(urlOutput)">复制结果</div>
        <div class="codec-btn codec-btn-danger" @click="urlInput = ''; urlOutput = ''">清空</div>
        <label class="codec-mode">
          <input type="checkbox" v-model="urlComponentMode" />
          <span>组件模式（编码 = / : ? 等全部保留字）</span>
        </label>
      </div>
      <div class="codec-block">
        <div class="codec-block-title">URL 编码</div>
        <textarea v-model="urlOutput" spellcheck="false" placeholder="编码结果 / 在此粘贴编码串进行解码"></textarea>
      </div>
    </div>
  </div>
</template>

<script>
  import {beautifyJsonString, jsonSimplify} from '@/util/json'
  export default {
    components: {},
    data(){
      return {
        ok: false,
        jsonVal: "",
        jsonResults: [],
        btnHover: false,
        tab: 'json',
        base64Input: "",
        base64Output: "",
        urlInput: "",
        urlOutput: "",
        urlComponentMode: true
      }
    },
    computed: {
      jsonLength() {
        return this.jsonVal ? this.jsonVal.length : 0;
      }
    },
    mounted(){
    },
    methods: {
      jsonFormat() {
        if(this.jsonVal !== '') {
          this.jsonResults = beautifyJsonString(this.jsonVal);
          this.jsonVal = this.jsonResults.join("\n");
        }
      },
      jsonStringify() {
        this.jsonFormat();
        this.jsonVal = jsonSimplify(this.jsonResults);
        this.jsonResults = [];
      },
      copyJson() {
        if(this.jsonVal === '') {
          return;
        }
        let self = this;
        let textarea = document.createElement('textarea');
        textarea.value = this.jsonVal;
        document.body.appendChild(textarea);
        textarea.select();
        try {
          document.execCommand('copy');
          self.ok = true;
          setTimeout(() => {
            self.ok = false;
          }, 1500);
        } catch (e) {
          self.ok = false;
        }
        document.body.removeChild(textarea);
      },
      clearJson() {
        this.jsonVal = "";
        this.jsonResults = [];
      },
      /* ---------------- Base64（UTF-8 安全） ---------------- */
      base64Encode() {
        if (!this.base64Input) return;
        const bytes = new TextEncoder().encode(this.base64Input);
        let bin = "";
        bytes.forEach((b) => (bin += String.fromCharCode(b)));
        this.base64Output = btoa(bin);
      },
      base64Decode() {
        if (!this.base64Output) return;
        try {
          const bin = atob(this.base64Output.trim());
          const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
          this.base64Input = new TextDecoder().decode(bytes);
        } catch (e) {
          this.$message.warning("不是合法的 Base64 字符串");
        }
      },
      /* ---------------- URL 编解码 ---------------- */
      urlEncode() {
        if (!this.urlInput) return;
        this.urlOutput = this.urlComponentMode
          ? encodeURIComponent(this.urlInput)
          : encodeURI(this.urlInput);
      },
      urlDecode() {
        if (!this.urlOutput) return;
        try {
          this.urlInput = this.urlComponentMode
            ? decodeURIComponent(this.urlOutput)
            : decodeURI(this.urlOutput);
        } catch (e) {
          this.$message.warning("不是合法的 URL 编码串");
        }
      },
      copyCodec(text) {
        if (!text) return;
        const done = () => this.$message.success("已复制");
        const fallback = () => {
          const ta = document.createElement("textarea");
          ta.value = text;
          document.body.appendChild(ta);
          ta.select();
          try { document.execCommand("copy"); done(); } catch (e) { this.$message.error("复制失败"); }
          document.body.removeChild(ta);
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(done, fallback);
        } else {
          fallback();
        }
      }
    }
  }
</script>

