<template>
  <div class="PhotoShop">
    <!-- 顶部主菜单 -->
    <div class="ps-menubar" @mouseleave="openMenu = null">
      <div v-for="menu in menuDefs" :key="menu.name" class="ps-menu-item"
           :class="{active: openMenu === menu.name}"
           @click.stop="toggleMenu(menu.name)"
           @mouseover="hoverMenu(menu.name)">
        <span class="ps-menu-label">{{ menu.name }}</span>
        <div class="ps-dropdown" v-if="openMenu === menu.name">
          <div v-for="item in menu.items" :key="item.label" class="ps-dropdown-item"
               @click.stop="runAction(item.act)">{{ item.label }}</div>
        </div>
      </div>
    </div>

    <!-- 子菜单：工具属性栏 + 撤销 -->
    <div class="ps-subbar">
      <div class="ps-attr">
        <template v-if="tool==='brush'||tool==='eraser'||tool==='rect'||tool==='ellipse'||tool==='line'">
          <span class="ps-attr-label">大小：</span>
          <input type="range" min="1" max="100" v-model.number="size">
          <span class="ps-attr-value">{{ size }}px</span>
          <label class="ps-attr-check" v-if="tool==='rect'||tool==='ellipse'">
            <input type="checkbox" v-model="shapeFill">填充
          </label>
        </template>
        <template v-else-if="tool==='text'">
          <template v-if="floatingText">
            <span class="ps-attr-hint">拖动文字调整位置 · 双击文字修改内容</span>
            <div >颜色:</div>
            <input type="color" v-model="floatingText.color" class="ps-color-picker">
            <button class="ps-btn-mini-top" @click="editFloatingText" title="修改文字内容/字号">修改</button>
            <button class="ps-btn-mini-top" @click="commitText" title="Enter 保存">保存</button>
            <button class="ps-btn-mini-top" @click="cancelText" title="Esc 取消">取消</button>
          </template>
          <template v-else>
            <span class="ps-attr-label">字号：</span>
            <input type="number" min="8" max="200" v-model.number="fontSize" class="ps-num-input">
            <span class="ps-attr-hint">点击画布位置添加文字</span>
          </template>
        </template>
        <template v-else-if="tool==='cropImage'">
          <span class="ps-attr-hint">拖动绘制裁剪区域，拖动边缘/角点调整</span>
          <template v-if="crop">
            <button class="ps-btn-mini-top" @click="commitCrop" title="Enter 确认">确认</button>
            <button class="ps-btn-mini-top" @click="cancelCrop" title="Esc 取消">取消</button>
          </template>
        </template>
        <span class="ps-attr-hint" v-else>{{ toolHint }}</span>
      </div>
      <button class="ps-btn" :disabled="!undoStack.length" @click="undo" title="撤销 Ctrl+Z">↶ 撤销</button>
      <button class="ps-btn" :disabled="!redoStack.length" @click="redo" title="重做 Ctrl+Y">↷ 重做</button>
    </div>

    <div class="ps-body">
      <!-- 左侧工具栏 -->
      <div class="ps-tools">
        <div v-for="t in tools" :key="t.id" class="ps-tool" :class="{active: tool===t.id}"
             :title="t.label" @click="switchTool(t.id)">
          <span class="ps-tool-name">{{ t.label }}</span>
        </div>
      </div>

      <!-- 中间画布区 -->
      <div class="ps-middle">
        <div class="ps-scroll" ref="scrollBox" @wheel="onCanvasWheel">
          <div class="ps-canvas-block" v-if="layers.length">
            <div class="ps-corner"></div>
            <canvas class="ps-ruler-top" ref="rulerTop"></canvas>
            <canvas class="ps-ruler-left" ref="rulerLeft"></canvas>
            <div class="ps-canvas-holder">
              <canvas ref="mainCanvas" class="ps-main-canvas"
                      :style="canvasCursorStyle"
                      @mousedown.prevent="onCanvasDown"
                      @mousemove="onCanvasHover"
                      @mouseleave="mouse = {x: null, y: null}"
                      @dblclick="onCanvasDblClick"
                      @contextmenu.prevent="onCanvasContextMenu"></canvas>
            </div>
          </div>
          <!-- 套索选区右键菜单 -->
          <div v-if="selMenu.visible" class="ps-sel-menu"
               :style="{left: selMenu.x + 'px', top: selMenu.y + 'px'}"
               @click.stop>
            <div class="ps-sel-menu-item" @click="invertSelection(); closeSelMenu()">反选</div>
            <div class="ps-sel-menu-item" @click="fillSelection(); closeSelMenu()">填充</div>
            <div class="ps-sel-menu-item" @click="freeTransformStart(); closeSelMenu()">自由变换</div>
            <div class="ps-sel-menu-item" @click="cropToSelection(); closeSelMenu()">裁剪</div>
            <div class="ps-sel-menu-sep"></div>
            <div class="ps-sel-menu-item" @click="copySelection(); closeSelMenu()">拷贝</div>
            <div class="ps-sel-menu-item" @click="pasteFromClipboard(); closeSelMenu()">粘贴</div>
            <div class="ps-sel-menu-sep"></div>
            <div class="ps-sel-menu-item danger" @click="deleteSelection(); closeSelMenu()">删除</div>
          </div>
          <!-- 裁剪右键菜单 -->
          <div v-if="cropMenu.visible" class="ps-sel-menu"
               :style="{left: cropMenu.x + 'px', top: cropMenu.y + 'px'}"
               @click.stop>
            <div class="ps-sel-menu-item" @click="commitCrop(); closeCropMenu()">确认裁剪</div>
            <div class="ps-sel-menu-item" @click="cancelCrop(); closeCropMenu()">取消裁剪</div>
          </div>
        </div>
        <div class="ps-statusbar">
          <span>缩放：{{ zoomPercent }}%</span>
          <button class="ps-btn-mini" @click="zoomIn">＋</button>
          <button class="ps-btn-mini" @click="zoomOut">－</button>
          <button class="ps-btn-mini" @click="zoom100">100%</button>
          <button class="ps-btn-mini" @click="zoomFit">适应</button>
          <span class="ps-status-hint">{{ toolHint }}</span>
        </div>
      </div>

      <!-- 右侧面板 -->
      <div class="ps-panels">
        <div class="ps-block">
          <h3 class="ps-block-title toggle" @click="toggleBlock('colors')">颜色</h3>
          <div v-show="blocks.colors" class="ps-block-body">
            <div class="ps-color-row">
              <input type="color" v-model="color" class="ps-color-picker">
              <span class="ps-color-label">十六进制</span>
              <input type="text" v-model="color" class="ps-hex-input" maxlength="7">
            </div>
            <div class="ps-swatches">
              <span v-for="s in swatches" :key="s" class="ps-swatch" :style="{background: s}"
                    @click="color = s"></span>
            </div>
          </div>
        </div>

        <div class="ps-block">
          <h3 class="ps-block-title toggle" @click="toggleBlock('info')">信息</h3>
          <div v-show="blocks.info" class="ps-block-body">
            <div class="ps-info-row"><span>尺寸：</span><span>{{ docWidth }} x {{ docHeight }} px</span></div>
            <div class="ps-info-row"><span>鼠标：</span><span>{{ mouseText }} px</span></div>
            <div class="ps-info-row"><span>分辨率：</span><span>72</span></div>
          </div>
        </div>

        <div class="ps-block">
          <h3 class="ps-block-title toggle" @click="toggleBlock('details')">图层详情</h3>
          <div v-if="blocks.details && activeLayer" class="ps-block-body">
            <div class="ps-info-row"><span>X：</span>
              <input type="number" v-model.number="activeLayer.x" @input="renderAll" class="ps-num-input"></div>
            <div class="ps-info-row"><span>Y：</span>
              <input type="number" v-model.number="activeLayer.y" @input="renderAll" class="ps-num-input"></div>
            <div class="ps-info-row"><span>宽度：</span>
              <span>{{ activeLayer.canvas.width }} px</span></div>
            <div class="ps-info-row"><span>高度：</span>
              <span>{{ activeLayer.canvas.height }} px</span></div>
            <div class="ps-info-row"><span>旋转：</span>
              <input type="number" v-model.number="activeLayer.rotation" @input="renderAll" class="ps-num-input"></div>
            <div class="ps-info-row ps-opacity-row"><span>不透明度：</span>
              <input type="range" min="0" max="100" v-model.number="activeLayer.opacity" @input="renderAll"
                     class="ps-opacity-range">
              <span class="ps-attr-value">{{ activeLayer.opacity }}%</span></div>
            <div class="ps-info-row"><span>颜色：</span>
              <input type="color" v-model="color" class="ps-color-picker"></div>
          </div>
        </div>

        <div class="ps-block ps-layers-block">
          <h3 class="ps-block-title">图层</h3>
          <div class="ps-block-body">
            <div class="ps-layer-row" v-for="l in layersReversed" :key="l.id"
                 :class="{active: l.id === activeLayerId}" @click="activeLayerId = l.id">
              <span class="ps-layer-eye" @click.stop="toggleLayerVisible(l)"
                    :title="l.visible ? '隐藏图层' : '显示图层'">{{ l.visible ? '●' : '○' }}</span>
              <span class="ps-layer-name">{{ l.name }}</span>
              <span class="ps-layer-opacity">{{ l.opacity }}%</span>
            </div>
            <div class="ps-layer-actions">
              <button class="ps-btn-mini" @click="addLayer" title="新建图层">＋</button>
              <button class="ps-btn-mini" @click="dupLayer" title="复制图层">⧉</button>
              <button class="ps-btn-mini" @click="deleteLayer" title="删除图层">✕</button>
              <button class="ps-btn-mini" @click="layerUp" title="上移">↑</button>
              <button class="ps-btn-mini" @click="layerDown" title="下移">↓</button>
            </div>
          </div>
        </div>
      </div>
    </div>

    <input type="file" ref="fileInput" accept="image/*" style="display:none" @change="openImageFile">

    <!-- 文字弹窗 -->
    <div class="ps-modal-mask" v-if="textModal.visible">
      <div class="ps-modal">
        <h3>{{ textModal.isEdit ? '修改文字' : '添加文字' }}</h3>
        <div class="ps-modal-row"><span>内容：</span>
          <input type="text" v-model="textModal.content" class="ps-text-input"></div>
        <div class="ps-modal-row"><span>字号：</span>
          <input type="number" min="8" v-model.number="textModal.size" class="ps-text-input"></div>
        <div class="ps-modal-row"><span>颜色：</span>
          <input type="color" v-model="textModal.color" class="ps-color-picker"></div>
        <div class="ps-modal-actions">
          <button class="ps-btn ps-btn-primary" @click="confirmText">确定</button>
          <button class="ps-btn" @click="textModal.visible = false">取消</button>
        </div>
      </div>
    </div>

    <!-- 尺寸弹窗 -->
    <div class="ps-modal-mask" v-if="sizeModal.visible">
      <div class="ps-modal">
        <h3>{{ sizeModal.mode === 'new' ? '新建画布' : '调整尺寸' }}</h3>
        <div class="ps-modal-row"><span>宽度：</span>
          <input type="number" min="1" v-model.number="sizeModal.width" class="ps-text-input"></div>
        <div class="ps-modal-row"><span>高度：</span>
          <input type="number" min="1" v-model.number="sizeModal.height" class="ps-text-input"></div>
        <div class="ps-modal-actions">
          <button class="ps-btn ps-btn-primary" @click="confirmSize">确定</button>
          <button class="ps-btn" @click="sizeModal.visible = false">取消</button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'PhotoShop',
  data() {
    return {
      // 当前打开的图片文件名（导出时沿用同名，浏览器环境没有本地路径）
      sourceFileName: '',
      docWidth: 800,
      docHeight: 600,
      layers: [],
      activeLayerId: null,
      idSeq: 0,
      layerNameSeq: 1,
      tool: 'move',
      color: '#000000',
      size: 2,
      fontSize: 32,
      shapeFill: false,
      zoom: 1,
      mouse: {x: null, y: null},
      undoStack: [],
      redoStack: [],
      openMenu: null,
      dragState: null,
      blocks: {colors: true, info: true, details: true},
      textModal: {visible: false, content: '', size: 32, color: '#000000', x: 0, y: 0, isEdit: false},
      // 浮动文字：文字输入后进入可拖动状态，保存后才固定绘制到图层
      floatingText: null,
      // 套索选区：闭合路径 + 边界框 + 选区遮罩（在主画布坐标系）
      // points: [{x,y},...] 已闭合；bounds: {minX,minY,maxX,maxY}
      // 运行时拖动状态: lassoDraft = {points: [...]}  shapeDraft = {shape, start, end}
      selection: null,
      lassoDraft: null,
      shapeDraft: null,
      // 自由变换时鼠标悬停的手柄类型（用于设置光标样式）
      transformHover: null,
      // 裁剪框：{x, y, w, h}（主画布坐标系），确认前可拖动边缘/角点调整
      crop: null,
      // 裁剪模式下鼠标悬停的光标样式
      cropHover: null,
      // 裁剪右键菜单
      cropMenu: {visible: false, x: 0, y: 0},
      // 选区右键菜单
      selMenu: {visible: false, x: 0, y: 0, inSelection: false},
      // 内部剪贴板（拷贝/粘贴选区内容）
      clipboard: null,
      // 自由变换模式：保留原始选区图像，通过手柄缩放变换中内容
      // transform = {origImage, origX, origY, origW, origH, x, y, w, h, handle}
      transform: null,
      sizeModal: {visible: false, width: 800, height: 600, mode: 'new'},
      swatches: ['#000000', '#ffffff', '#ff0000', '#00ff00', '#0000ff',
                 '#ffff00', '#00ffff', '#ff00ff', '#808080', '#c0c0c0'],
      tools: [
        {id: 'move', label: '移动'},
        {id: 'cropImage', label: '裁剪'},
        {id: 'brush', label: '画笔'},
        {id: 'lasso', label: '套索'},
        {id: 'rectLasso', label: '矩形套索'},
        {id: 'ellipseLasso', label: '椭圆套索'},
        {id: 'eraser', label: '橡皮擦'},
        {id: 'fill', label: '油漆桶'},
        {id: 'text', label: '文字'},
        {id: 'rect', label: '矩形'},
        {id: 'ellipse', label: '椭圆'},
        {id: 'line', label: '直线'},
        {id: 'eyedropper', label: '吸管'}
      ],
      menuDefs: [
        {name: '文件', items: [
          {label: '新建...', act: 'newDoc'},
          {label: '打开图片...', act: 'openImage'},
          {label: '导出 PNG', act: 'exportPNG'},
          {label: '导出 JPG', act: 'exportJPG'}
        ]},
        {name: '编辑', items: [
          {label: '撤销', act: 'undo'},
          {label: '重做', act: 'redo'},
          {label: '清空画布', act: 'clearCanvas'}
        ]},
        {name: '视图', items: [
          {label: '放大', act: 'zoomIn'},
          {label: '缩小', act: 'zoomOut'},
          {label: '实际大小 (100%)', act: 'zoom100'},
          {label: '适应窗口', act: 'zoomFit'}
        ]},
        {name: '图片', items: [
          {label: '调整尺寸...', act: 'resizeDoc'},
          {label: '水平翻转', act: 'flipH'},
          {label: '垂直翻转', act: 'flipV'},
          {label: '顺时针旋转 90°', act: 'rotate90'}
        ]},
        {name: '图层', items: [
          {label: '新建图层', act: 'addLayer'},
          {label: '复制图层', act: 'dupLayer'},
          {label: '删除图层', act: 'deleteLayer'},
          {label: '图层上移', act: 'layerUp'},
          {label: '图层下移', act: 'layerDown'},
          {label: '向下合并', act: 'mergeDown'}
        ]},
        {name: '特效', items: [
          {label: '灰度', act: 'fx-gray'},
          {label: '反色', act: 'fx-invert'},
          {label: '模糊', act: 'fx-blur'},
          {label: '锐化', act: 'fx-sharpen'},
          {label: '变亮', act: 'fx-brighten'},
          {label: '变暗', act: 'fx-darken'}
        ]}
      ]
    }
  },
  computed: {
    activeLayer() {
      return this.layers.find(l => l.id === this.activeLayerId) || null;
    },
    layersReversed() {
      return this.layers.slice().reverse();
    },
    displayW() {
      return Math.round(this.docWidth * this.zoom);
    },
    displayH() {
      return Math.round(this.docHeight * this.zoom);
    },
    zoomPercent() {
      return Math.round(this.zoom * 100);
    },
    canvasCursorStyle() {
      const style = {width: this.displayW + 'px', height: this.displayH + 'px'};
      if (this.tool === 'brush' || this.tool === 'eraser') {
        const d = Math.max(2, Math.round(this.size * this.zoom));
        const half = d / 2;
        const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + d + '" height="' + d + '">'
          + '<circle cx="' + half + '" cy="' + half + '" r="' + (half - 0.5) + '" fill="none" stroke="#000" stroke-width="1"/>'
          + '<circle cx="' + half + '" cy="' + half + '" r="' + (half - 1.5) + '" fill="none" stroke="#fff" stroke-width="1"/>'
          + '</svg>';
        style.cursor = 'url(\'data:image/svg+xml;base64,' + btoa(svg) + '\') ' + half + ' ' + half + ', crosshair';
      } else if (this.cropHover) {
        style.cursor = this.cropHover;
      } else if (this.transformHover) {
        style.cursor = this.transformHover;
      } else if (this.transform) {
        style.cursor = 'move';
      } else {
        style.cursor = 'crosshair';
      }
      return style;
    },
    mouseText() {
      if (this.mouse.x === null || this.mouse.y === null) return '-';
      return this.mouse.x + ' , ' + this.mouse.y;
    },
    toolHint() {
      if (this.tool === 'text' && this.floatingText) {
        return '在文字上按下拖动可调整位置 · 保存=固定 · Esc=取消';
      }
      const hints = {
        move: '拖动移动当前图层',
        cropImage: '拖动绘制裁剪区域 · 拖动边缘/角点调整 · Enter/双击确认 · Esc 取消',
        lasso: '按住鼠标绘制自由选区，松开自动闭合',
        rectLasso: '拖动绘制矩形选区',
        ellipseLasso: '拖动绘制椭圆选区',
        brush: '按住鼠标在画布上绘制',
        eraser: '按住鼠标擦除当前图层',
        fill: '点击画布进行颜色填充',
        text: '点击画布位置添加文字',
        rect: '拖动绘制矩形',
        ellipse: '拖动绘制椭圆',
        line: '拖动绘制直线',
        eyedropper: '点击画布拾取颜色'
      };
      return hints[this.tool] || '';
    }
  },
  watch: {
    // 浮动文字颜色变化时重绘预览
    'floatingText.color'() {
      if (this.floatingText) this.renderMain();
    }
  },
  mounted() {
    this.initDoc();
    window.addEventListener('keydown', this.onKeydown);
    window.addEventListener('click', this.onWindowClick);
    this.marchingTimer = setInterval(() => {
      // 有选区时持续刷新主画布以产生蚂蚁线动画
      if (this.selection && !this.lassoDraft && this.$refs.mainCanvas) {
        this.renderMain();
      }
    }, 80);
  },
  beforeDestroy() {
    window.removeEventListener('keydown', this.onKeydown);
    window.removeEventListener('click', this.onWindowClick);
    if (this.marchingTimer) clearInterval(this.marchingTimer);
  },
  methods: {
    /* ========== 初始化 ========== */
    initDoc() {
      // 初始不创建默认背景图层，画布保持空白；用户可通过「图层 → 新建图层」添加
      this.layers = [];
      this.activeLayerId = null;
      this.undoStack = [];
      this.redoStack = [];
      this.selection = null;
      this.lassoDraft = null;
      this.shapeDraft = null;
      this.transform = null;
      this.crop = null;
      this.cropMenu.visible = false;
      this.renderAll();
    },
    makeLayer(name) {
      const canvas = document.createElement('canvas');
      canvas.width = this.docWidth;
      canvas.height = this.docHeight;
      return {
        id: ++this.idSeq,
        name: name,
        visible: true,
        opacity: 100,
        x: 0,
        y: 0,
        rotation: 0,
        canvas: canvas
      };
    },
    cloneCanvas(src) {
      const c = document.createElement('canvas');
      c.width = src.width;
      c.height = src.height;
      c.getContext('2d').drawImage(src, 0, 0);
      return c;
    },
    /* ========== 渲染 ========== */
    renderAll() {
      this.renderMain();
      this.renderRulers();
    },
    renderMain() {
      const c = this.$refs.mainCanvas;
      if (!c) return;
      if (c.width !== this.docWidth) c.width = this.docWidth;
      if (c.height !== this.docHeight) c.height = this.docHeight;
      const ctx = c.getContext('2d');
      ctx.clearRect(0, 0, c.width, c.height);
      for (const l of this.layers) {
        if (!l.visible || l.opacity <= 0) continue;
        ctx.save();
        ctx.globalAlpha = l.opacity / 100;
        const w = l.canvas.width, h = l.canvas.height;
        ctx.translate(l.x + w / 2, l.y + h / 2);
        ctx.rotate(l.rotation * Math.PI / 180);
        ctx.drawImage(l.canvas, -w / 2, -h / 2);
        ctx.restore();
      }
      // 渲染浮动文字：未固定前不绘制到图层，只在主画布上预览，并用虚线边框提示可拖动
      const ft = this.floatingText;
      if (ft) {
        ctx.save();
        ctx.font = ft.size + 'px "Microsoft YaHei", sans-serif';
        ctx.fillStyle = ft.color;
        ctx.textBaseline = 'top';
        ctx.fillText(ft.content, ft.x, ft.y);
        // 虚线选框提示当前为可拖动的浮动状态
        ctx.strokeStyle = '#00a1ff';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 3]);
        ctx.strokeRect(ft.x - 1, ft.y - 1, ft.width + 2, ft.height + 2);
        ctx.restore();
      }
      // 渲染套索拖动中的轨迹（未闭合）
      if (this.lassoDraft && this.lassoDraft.points.length > 1) {
        const pts = this.lassoDraft.points;
        ctx.save();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 1 / this.zoom;
        ctx.setLineDash([3 / this.zoom, 3 / this.zoom]);
        ctx.beginPath();
        ctx.moveTo(pts[0].x, pts[0].y);
        for (let i = 1; i < pts.length; i++) {
          ctx.lineTo(pts[i].x, pts[i].y);
        }
        ctx.stroke();
        ctx.restore();
      }
      // 渲染矩形/椭圆套索拖动中的预览
      if (this.shapeDraft) {
        const d = this.shapeDraft;
        const minX = Math.min(d.start.x, d.end.x);
        const minY = Math.min(d.start.y, d.end.y);
        const w = Math.abs(d.end.x - d.start.x);
        const h = Math.abs(d.end.y - d.start.y);
        ctx.save();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 1 / this.zoom;
        ctx.setLineDash([3 / this.zoom, 3 / this.zoom]);
        if (d.shape === 'rect') {
          ctx.strokeRect(minX, minY, w, h);
        } else {
          ctx.beginPath();
          ctx.ellipse(minX + w / 2, minY + h / 2, w / 2, h / 2, 0, 0, Math.PI * 2);
          ctx.stroke();
        }
        ctx.restore();
      }
      // 渲染已闭合的选区：先绘制选区内容（浮动图像），再绘制蚂蚁线
      const sel = this.selection;
      if (sel && sel.image) {
        ctx.save();
        // 自由变换模式下，绘制变换后的尺寸（基于 transform 框）
        if (this.transform) {
          const t = this.transform;
          ctx.drawImage(t.origImage, t.x, t.y, t.w, t.h);
        } else {
          ctx.drawImage(sel.image, sel.x, sel.y);
        }
        ctx.restore();
      }
      if (sel && sel.points && sel.points.length > 1 && !this.transform) {
        const drawMarchingAnts = (pts) => {
          ctx.save();
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 1 / this.zoom;
          ctx.setLineDash([4 / this.zoom, 4 / this.zoom]);
          ctx.lineDashOffset = -((Date.now() / 80) % (8 / this.zoom));
          ctx.beginPath();
          ctx.moveTo(pts[0].x, pts[0].y);
          for (let i = 1; i < pts.length; i++) {
            ctx.lineTo(pts[i].x, pts[i].y);
          }
          ctx.closePath();
          ctx.stroke();
          ctx.restore();
        };
        drawMarchingAnts(sel.points);
        if (sel.inverted && sel.originalPoints && sel.originalPoints.length > 1) {
          drawMarchingAnts(sel.originalPoints);
        }
      }
      // 自由变换模式：绘制变换框和 8 个手柄
      if (this.transform) {
        const t = this.transform;
        ctx.save();
        // 变换框：黑色细线 + 白色虚线
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 1 / this.zoom;
        ctx.setLineDash([]);
        ctx.strokeRect(t.x, t.y, t.w, t.h);
        ctx.strokeStyle = '#fff';
        ctx.setLineDash([3 / this.zoom, 3 / this.zoom]);
        ctx.strokeRect(t.x, t.y, t.w, t.h);
        ctx.setLineDash([]);
        // 8 个手柄：小方块
        const hs = 6 / this.zoom; // 手柄边长（屏幕 6px）
        for (const h of this.transformHandles()) {
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#000000';
          ctx.lineWidth = 1 / this.zoom;
          ctx.fillRect(h.x - hs / 2, h.y - hs / 2, hs, hs);
          ctx.strokeRect(h.x - hs / 2, h.y - hs / 2, hs, hs);
        }
        ctx.restore();
      }
      // 裁剪模式：框外压暗 + 三分线 + 边框 + 8 个手柄
      const cr = this.crop;
      if (cr && cr.w > 0 && cr.h > 0) {
        ctx.save();
        const dw = this.docWidth, dh = this.docHeight;
        // 框外压暗
        ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
        ctx.fillRect(0, 0, dw, Math.max(0, cr.y));
        ctx.fillRect(0, cr.y + cr.h, dw, Math.max(0, dh - cr.y - cr.h));
        ctx.fillRect(0, cr.y, Math.max(0, cr.x), cr.h);
        ctx.fillRect(cr.x + cr.w, cr.y, Math.max(0, dw - cr.x - cr.w), cr.h);
        // 三分线
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
        ctx.lineWidth = 1 / this.zoom;
        ctx.beginPath();
        for (let i = 1; i <= 2; i++) {
          const gx = cr.x + (cr.w * i) / 3;
          const gy = cr.y + (cr.h * i) / 3;
          ctx.moveTo(gx, cr.y);
          ctx.lineTo(gx, cr.y + cr.h);
          ctx.moveTo(cr.x, gy);
          ctx.lineTo(cr.x + cr.w, gy);
        }
        ctx.stroke();
        // 边框：黑实线 + 白虚线
        ctx.strokeStyle = '#000';
        ctx.strokeRect(cr.x, cr.y, cr.w, cr.h);
        ctx.strokeStyle = '#fff';
        ctx.setLineDash([3 / this.zoom, 3 / this.zoom]);
        ctx.strokeRect(cr.x, cr.y, cr.w, cr.h);
        ctx.setLineDash([]);
        // 8 个手柄
        const chs = 6 / this.zoom;
        for (const h of this.cropHandles()) {
          ctx.fillStyle = '#ffffff';
          ctx.strokeStyle = '#000000';
          ctx.lineWidth = 1 / this.zoom;
          ctx.fillRect(h.x - chs / 2, h.y - chs / 2, chs, chs);
          ctx.strokeRect(h.x - chs / 2, h.y - chs / 2, chs, chs);
        }
        ctx.restore();
      }
    },
    compositeTo(ctx) {
      for (const l of this.layers) {
        if (!l.visible || l.opacity <= 0) continue;
        ctx.save();
        ctx.globalAlpha = l.opacity / 100;
        const w = l.canvas.width, h = l.canvas.height;
        ctx.translate(l.x + w / 2, l.y + h / 2);
        ctx.rotate(l.rotation * Math.PI / 180);
        ctx.drawImage(l.canvas, -w / 2, -h / 2);
        ctx.restore();
      }
      // 浮动选区（套索剪出的像素只存在于 selection.image，图层上是透明洞），
      // 必须与画布显示一致地参与导出合成，否则导出结果会丢失选区内容
      const sel = this.selection;
      if (sel && sel.image) {
        if (this.transform) {
          const t = this.transform;
          ctx.drawImage(t.origImage, t.x, t.y, t.w, t.h);
        } else {
          ctx.drawImage(sel.image, sel.x, sel.y);
        }
      }
      // 浮动文字（未固定到图层前同样不在任何图层上）
      const ft = this.floatingText;
      if (ft && ft.visible && ft.content) {
        ctx.save();
        ctx.font = ft.size + 'px sans-serif';
        ctx.fillStyle = ft.color;
        ctx.textBaseline = 'top';
        ctx.fillText(ft.content, ft.x, ft.y);
        ctx.restore();
      }
    },
    renderRulers() {
      const t = this.$refs.rulerTop;
      const l = this.$refs.rulerLeft;
      if (!t || !l) return;
      const z = this.zoom;
      const dw = this.displayW, dh = this.displayH;
      t.width = dw; t.height = 18;
      l.width = 18; l.height = dh;
      const tc = t.getContext('2d'), lc = l.getContext('2d');
      tc.fillStyle = '#2a2a2e'; tc.fillRect(0, 0, dw, 18);
      lc.fillStyle = '#2a2a2e'; lc.fillRect(0, 0, 18, dh);
      let step = 10;
      while (step * z < 8) step *= 2;
      const major = step * 5;
      tc.strokeStyle = '#5a5a5f'; lc.strokeStyle = '#5a5a5f';
      tc.fillStyle = '#9a9aa0'; lc.fillStyle = '#9a9aa0';
      tc.font = '9px sans-serif'; lc.font = '9px sans-serif';
      tc.beginPath(); lc.beginPath();
      for (let x = 0; x <= this.docWidth; x += step) {
        const sx = Math.round(x * z) + 0.5;
        const isMajor = x % major === 0;
        tc.moveTo(sx, isMajor ? 4 : 10);
        tc.lineTo(sx, 18);
        if (isMajor && x > 0) tc.fillText(String(x), sx + 2, 9);
      }
      for (let y = 0; y <= this.docHeight; y += step) {
        const sy = Math.round(y * z) + 0.5;
        const isMajor = y % major === 0;
        lc.moveTo(isMajor ? 4 : 10, sy);
        lc.lineTo(18, sy);
        if (isMajor && y > 0) {
          lc.save();
          lc.translate(9, sy - 2);
          lc.rotate(-Math.PI / 2);
          lc.fillText(String(y), 0, 0);
          lc.restore();
        }
      }
      tc.stroke(); lc.stroke();
    },
    /* ========== 历史记录 ========== */
    makeSnapshot() {
      return {
        docWidth: this.docWidth,
        docHeight: this.docHeight,
        activeLayerId: this.activeLayerId,
        layers: this.layers.map(l => ({
          id: l.id, name: l.name, visible: l.visible, opacity: l.opacity,
          x: l.x, y: l.y, rotation: l.rotation,
          canvas: this.cloneCanvas(l.canvas)
        })),
        selection: this.cloneSelection(this.selection)
      };
    },
    cloneSelection(sel) {
      if (!sel) return null;
      return {
        points: sel.points.map(p => ({x: p.x, y: p.y})),
        bounds: Object.assign({}, sel.bounds),
        image: sel.image ? this.cloneCanvas(sel.image) : null,
        x: sel.x,
        y: sel.y,
        layerId: sel.layerId,
        committed: sel.committed,
        inverted: !!sel.inverted,
        originalPoints: sel.originalPoints ? sel.originalPoints.map(p => ({x: p.x, y: p.y})) : null
      };
    },
    applySnapshot(s) {
      this.docWidth = s.docWidth;
      this.docHeight = s.docHeight;
      this.activeLayerId = s.activeLayerId;
      this.layers = s.layers.map(l => Object.assign({}, l, {canvas: this.cloneCanvas(l.canvas)}));
      // 选区状态随快照恢复（再次深拷贝，避免与历史栈共享 canvas）
      this.selection = this.cloneSelection(s.selection);
      // 清理瞬态交互状态
      this.transform = null;
      this.crop = null;
      this.cropMenu.visible = false;
      this.lassoDraft = null;
      this.shapeDraft = null;
      this.selMenu.visible = false;
      this.renderAll();
    },
    pushHistory() {
      this.undoStack.push(this.makeSnapshot());
      if (this.undoStack.length > 25) this.undoStack.shift();
      this.redoStack = [];
    },
    undo() {
      if (!this.undoStack.length) return;
      this.redoStack.push(this.makeSnapshot());
      this.applySnapshot(this.undoStack.pop());
    },
    redo() {
      if (!this.redoStack.length) return;
      this.undoStack.push(this.makeSnapshot());
      this.applySnapshot(this.redoStack.pop());
    },
    /* ========== 画布交互 ========== */
    getDocPos(e) {
      const rect = this.$refs.mainCanvas.getBoundingClientRect();
      return {
        x: (e.clientX - rect.left) / this.zoom,
        y: (e.clientY - rect.top) / this.zoom
      };
    },
    onCanvasHover(e) {
      const pos = this.getDocPos(e);
      this.mouse = {x: Math.round(pos.x), y: Math.round(pos.y)};
      // 裁剪模式下，根据鼠标位置设置边缘/角点光标
      if (this.tool === 'cropImage' && this.crop) {
        const c = this.crop;
        const handle = this.hitCropHandle(pos);
        this.cropHover = this.handleToCursor(handle,
          pos.x >= c.x && pos.x <= c.x + c.w &&
          pos.y >= c.y && pos.y <= c.y + c.h);
      } else {
        this.cropHover = null;
      }
      // 自由变换模式下，根据鼠标位置设置变换手柄光标
      if (this.transform) {
        const handle = this.hitTransformHandle(pos);
        this.transformHover = this.handleToCursor(handle,
          pos.x >= this.transform.x && pos.x <= this.transform.x + this.transform.w &&
          pos.y >= this.transform.y && pos.y <= this.transform.y + this.transform.h);
      } else {
        this.transformHover = null;
      }
    },
    handleToCursor(handle, inBox) {
      const cursors = {
        nw: 'nwse-resize', se: 'nwse-resize',
        ne: 'nesw-resize', sw: 'nesw-resize',
        n: 'ns-resize', s: 'ns-resize',
        e: 'ew-resize', w: 'ew-resize'
      };
      if (handle) return cursors[handle] || 'default';
      if (inBox) return 'move';
      return null;
    },
    onCanvasDblClick(e) {
      // 裁剪模式下双击框内 → 确认裁剪
      if (this.tool === 'cropImage' && this.crop) {
        const pos = this.getDocPos(e);
        const c = this.crop;
        if (pos.x >= c.x && pos.x <= c.x + c.w &&
            pos.y >= c.y && pos.y <= c.y + c.h) {
          this.commitCrop();
        }
        return;
      }
      // 双击浮动文字 → 打开编辑弹窗，可修改内容/字号/颜色
      if (this.tool === 'text' && this.floatingText) {
        const pos = this.getDocPos(e);
        if (this.hitFloatingText(pos)) {
          this.editFloatingText();
        }
      }
    },
    onCanvasDown(e) {
      // 只响应左键；右键交由 contextmenu 事件处理，避免误清空浮动选区
      if (e.button !== 0) return;
      const pos = this.getDocPos(e);
      const layer = this.activeLayer;
      if (this.tool === 'eyedropper') {
        this.pickColor(pos);
        return;
      }
      if (!layer) {
        if (this.tool === 'lasso' || this.tool === 'rectLasso' || this.tool === 'ellipseLasso'
            || this.tool === 'brush' || this.tool === 'eraser'
            || this.tool === 'fill' || this.tool === 'rect' || this.tool === 'ellipse'
            || this.tool === 'line') {
          // 无图层时无法操作这些工具，直接忽略
        }
        return;
      }
      // 自由变换模式：检测是否点中手柄或变换框内部
      if (this.transform) {
        const handle = this.hitTransformHandle(pos);
        if (handle) {
          // 启动手柄缩放
          this.dragState = {
            mode: 'transformScale',
            handle,
            startDoc: pos,
            orig: {x: this.transform.x, y: this.transform.y,
                   w: this.transform.w, h: this.transform.h}
          };
          this.bindWindowDrag();
          return;
        }
        // 点在变换框内 → 启动平移变换框
        if (pos.x >= this.transform.x && pos.x <= this.transform.x + this.transform.w &&
            pos.y >= this.transform.y && pos.y <= this.transform.y + this.transform.h) {
          this.dragState = {
            mode: 'transformMove',
            startDoc: pos,
            orig: {x: this.transform.x, y: this.transform.y}
          };
          this.bindWindowDrag();
          return;
        }
        // 点击变换框外 → 确认变换并退出
        this.commitTransform();
        return;
      }
      if (this.tool === 'text') {
        // 已存在浮动文字：在文字范围内按下 → 启动拖动；在文字范围外按下 → 固定后弹出新文字弹窗
        if (this.floatingText) {
          if (this.hitFloatingText(pos)) {
            this.dragState = {
              mode: 'floatText',
              startDoc: pos,
              startFx: this.floatingText.x,
              startFy: this.floatingText.y
            };
            this.bindWindowDrag();
            return;
          }
          this.commitText();
        }
        this.textModal = {
          visible: true, content: '', size: this.fontSize, color: this.color,
          x: Math.round(pos.x), y: Math.round(pos.y), isEdit: false
        };
        return;
      }
      // 切换到其他工具时，自动固定未保存的浮动文字
      if (this.floatingText) {
        this.commitText();
      }
      if (this.tool === 'cropImage') {
        this.startCropDrag(pos);
        return;
      }
      if (this.tool === 'lasso') {
        // 套索按下：清空旧选区（先写回未提交的浮动像素，避免丢像素），开始采集新路径
        this.clearSelection();
        this.lassoDraft = {points: [{x: pos.x, y: pos.y}]};
        this.bindWindowDrag();
        return;
      }
      if (this.tool === 'rectLasso' || this.tool === 'ellipseLasso') {
        this.clearSelection();
        this.shapeDraft = {
          shape: this.tool === 'rectLasso' ? 'rect' : 'ellipse',
          start: {x: pos.x, y: pos.y},
          end: {x: pos.x, y: pos.y}
        };
        this.bindWindowDrag();
        return;
      }
      this.pushHistory();
      if (this.tool === 'fill') {
        this.floodFill(layer, pos);
        this.renderAll();
        return;
      }
      if (this.tool === 'move') {
        // 若存在选区且鼠标落在选区范围内 → 启动选区内容拖动；否则按图层移动处理
        if (this.selection && this.pointInSelection(pos)) {
          // 填充后选区只有蚂蚁线：先从图层重新剪切出浮动像素
          this.ensureSelectionFloating();
          if (!this.selection.image) {
            this.dragState = {mode: 'move', startDoc: pos, startX: layer.x, startY: layer.y};
            this.bindWindowDrag();
            return;
          }
          this.dragState = {
            mode: 'selMove',
            startDoc: pos,
            startSelX: this.selection.x,
            startSelY: this.selection.y,
            moved: false
          };
          this.bindWindowDrag();
          return;
        }
        this.dragState = {mode: 'move', startDoc: pos, startX: layer.x, startY: layer.y};
        this.bindWindowDrag();
        return;
      }
      const lctx = layer.canvas.getContext('2d');
      const lp = {x: pos.x - layer.x, y: pos.y - layer.y};
      if (this.tool === 'brush' || this.tool === 'eraser') {
        this.dragState = {mode: 'draw', last: lp};
        this.strokeTo(lctx, lp, lp);
        this.renderAll();
        this.bindWindowDrag();
      } else {
        this.dragState = {
          mode: 'shape', start: lp,
          snapshot: lctx.getImageData(0, 0, layer.canvas.width, layer.canvas.height)
        };
        this.bindWindowDrag();
      }
    },
    bindWindowDrag() {
      window.addEventListener('mousemove', this.onWindowMove);
      window.addEventListener('mouseup', this.onWindowUp);
    },
    unbindWindowDrag() {
      window.removeEventListener('mousemove', this.onWindowMove);
      window.removeEventListener('mouseup', this.onWindowUp);
    },
    onWindowMove(e) {
      const pos = this.getDocPos(e);
      this.mouse = {x: Math.round(pos.x), y: Math.round(pos.y)};
      // 套索工具拖动采样（独立于 dragState，因为套索按下时未设置 dragState）
      if (this.lassoDraft && this.tool === 'lasso') {
        const pts = this.lassoDraft.points;
        const last = pts[pts.length - 1];
        // 距离阈值，避免点太密集
        const dx = pos.x - last.x, dy = pos.y - last.y;
        if (dx * dx + dy * dy > 4) {
          pts.push({x: pos.x, y: pos.y});
          this.renderAll();
        }
      }
      // 矩形/椭圆套索拖动中更新 end 点
      if (this.shapeDraft && (this.tool === 'rectLasso' || this.tool === 'ellipseLasso')) {
        this.shapeDraft.end = {x: pos.x, y: pos.y};
        this.renderAll();
      }
      if (!this.dragState) return;
      const layer = this.activeLayer;
      if (!layer) return;
      const lctx = layer.canvas.getContext('2d');
      const lp = {x: pos.x - layer.x, y: pos.y - layer.y};
      if (this.dragState.mode === 'draw') {
        this.strokeTo(lctx, this.dragState.last, lp);
        this.dragState.last = lp;
        this.renderAll();
      } else if (this.dragState.mode === 'move') {
        layer.x = Math.round(this.dragState.startX + pos.x - this.dragState.startDoc.x);
        layer.y = Math.round(this.dragState.startY + pos.y - this.dragState.startDoc.y);
        this.renderAll();
      } else if (this.dragState.mode === 'floatText') {
        const ft = this.floatingText;
        if (ft) {
          ft.x = Math.round(this.dragState.startFx + pos.x - this.dragState.startDoc.x);
          ft.y = Math.round(this.dragState.startFy + pos.y - this.dragState.startDoc.y);
          this.renderAll();
        }
      } else if (this.dragState.mode === 'shape') {
        lctx.putImageData(this.dragState.snapshot, 0, 0);
        this.drawShape(lctx, this.dragState.start, lp);
        this.renderAll();
      } else if (this.dragState.mode === 'cropNew' && this.crop) {
        // 新建裁剪框：从起点拖出矩形（限制在文档边缘内）
        const s = this.dragState.start;
        const px = Math.max(0, Math.min(this.docWidth, pos.x));
        const py = Math.max(0, Math.min(this.docHeight, pos.y));
        this.crop.x = Math.min(s.x, px);
        this.crop.y = Math.min(s.y, py);
        this.crop.w = Math.abs(px - s.x);
        this.crop.h = Math.abs(py - s.y);
        this.renderAll();
      } else if (this.dragState.mode === 'cropMove' && this.crop) {
        // 裁剪框整体平移（限制在文档边缘内）
        const c = this.crop;
        c.x = Math.max(0, Math.min(this.docWidth - c.w,
          this.dragState.orig.x + pos.x - this.dragState.startDoc.x));
        c.y = Math.max(0, Math.min(this.docHeight - c.h,
          this.dragState.orig.y + pos.y - this.dragState.startDoc.y));
        this.renderAll();
      } else if (this.dragState.mode === 'cropScale' && this.crop) {
        // 裁剪框边缘/角点拖动
        const c = this.crop;
        const o = this.dragState.orig;
        const handle = this.dragState.handle;
        const dx = pos.x - this.dragState.startDoc.x;
        const dy = pos.y - this.dragState.startDoc.y;
        let nx = o.x, ny = o.y, nr = o.x + o.w, nb = o.y + o.h;
        if (handle.indexOf('w') >= 0) nx = o.x + dx;
        if (handle.indexOf('e') >= 0) nr = o.x + o.w + dx;
        if (handle.indexOf('n') >= 0) ny = o.y + dy;
        if (handle.indexOf('s') >= 0) nb = o.y + o.h + dy;
        // 超过文档边缘时手柄固定在边缘上，不再移动
        nx = Math.max(0, nx);
        ny = Math.max(0, ny);
        nr = Math.min(this.docWidth, nr);
        nb = Math.min(this.docHeight, nb);
        // 最小尺寸限制：防止拖过对边
        const MIN = 4;
        if (handle.indexOf('w') >= 0) nx = Math.min(nx, nr - MIN);
        else nr = Math.max(nr, nx + MIN);
        if (handle.indexOf('n') >= 0) ny = Math.min(ny, nb - MIN);
        else nb = Math.max(nb, ny + MIN);
        c.x = nx;
        c.y = ny;
        c.w = nr - nx;
        c.h = nb - ny;
        this.renderAll();
      } else if (this.dragState.mode === 'selMove' && this.selection) {
        // 在选区内拖动 → 平移选区内容
        const dx = pos.x - this.dragState.startDoc.x;
        const dy = pos.y - this.dragState.startDoc.y;
        if (!this.dragState.moved) {
          this.dragState.moved = true;
          // 首次真正移动时快照（此刻选区仍在原位置）：撤销移动 = 选区回原位
          this.pushHistory();
        }
        const ft = this.selection;
        ft.x = Math.round(this.dragState.startSelX + dx);
        ft.y = Math.round(this.dragState.startSelY + dy);
        this.renderAll();
      } else if (this.dragState.mode === 'transformMove' && this.transform) {
        // 自由变换框整体平移
        const dx = pos.x - this.dragState.startDoc.x;
        const dy = pos.y - this.dragState.startDoc.y;
        this.transform.x = this.dragState.orig.x + dx;
        this.transform.y = this.dragState.orig.y + dy;
        this.renderAll();
      } else if (this.dragState.mode === 'transformScale' && this.transform) {
        // 自由变换框手柄缩放
        const t = this.transform;
        const o = this.dragState.orig;
        const handle = this.dragState.handle;
        const dx = pos.x - this.dragState.startDoc.x;
        const dy = pos.y - this.dragState.startDoc.y;
        let nx = o.x, ny = o.y, nw = o.w, nh = o.h;
        // 根据手柄 id 调整对应边
        if (handle.indexOf('w') >= 0) { nx = o.x + dx; nw = o.w - dx; }
        if (handle.indexOf('e') >= 0) { nw = o.w + dx; }
        if (handle.indexOf('n') >= 0) { ny = o.y + dy; nh = o.h - dy; }
        if (handle.indexOf('s') >= 0) { nh = o.h + dy; }
        // 最小尺寸限制：防止框被压缩到负数
        const MIN = 4;
        if (nw < MIN) {
          // 翻转处理：如果宽度被压缩到 < MIN，固定对边不动
          if (handle.indexOf('w') >= 0) { nx = o.x + o.w - MIN; }
          nw = MIN;
        }
        if (nh < MIN) {
          if (handle.indexOf('n') >= 0) { ny = o.y + o.h - MIN; }
          nh = MIN;
        }
        t.x = nx; t.y = ny; t.w = nw; t.h = nh;
        this.renderAll();
      }
    },
    onWindowUp() {
      this.unbindWindowDrag();
      // 套索闭合：把采集到的路径变成选区
      if (this.lassoDraft) {
        this.finalizeLasso();
      }
      // 矩形/椭圆套索闭合
      if (this.shapeDraft) {
        this.finalizeShapeLasso();
      }
      // 新建裁剪框结束：过小的框视为误触，丢弃
      if (this.dragState && this.dragState.mode === 'cropNew' && this.crop) {
        if (this.crop.w < 2 || this.crop.h < 2) {
          this.crop = null;
        }
        this.renderAll();
      }
      // 选区拖动结束：把内容写回图层
      if (this.dragState && this.dragState.mode === 'selMove' && this.selection) {
        this.commitSelectionMove();
      }
      this.dragState = null;
    },
    /* ========== 套索选区 ========== */
    pointInPoly(x, y, pts) {
      const n = pts.length;
      let inside = false;
      let j = n - 1;
      for (let i = 0; i < n; j = i++) {
        const pi = pts[i], pj = pts[j];
        if (((pi.y > y) !== (pj.y > y)) &&
            (x < (pj.x - pi.x) * (y - pi.y) / (pj.y - pi.y) + pi.x)) {
          inside = !inside;
        }
      }
      return inside;
    },
    pointInSelection(pos) {
      const sel = this.selection;
      if (!sel || !sel.points || sel.points.length < 3) return false;
      if (sel.inverted && sel.originalPoints) {
        return !this.pointInPoly(pos.x, pos.y, sel.originalPoints);
      }
      return this.pointInPoly(pos.x, pos.y, sel.points);
    },
    calcPolyBounds(pts) {
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      for (const p of pts) {
        if (p.x < minX) minX = p.x;
        if (p.y < minY) minY = p.y;
        if (p.x > maxX) maxX = p.x;
        if (p.y > maxY) maxY = p.y;
      }
      minX = Math.floor(minX);
      minY = Math.floor(minY);
      maxX = Math.ceil(maxX);
      maxY = Math.ceil(maxY);
      return {minX, minY, maxX, maxY, w: Math.max(1, maxX - minX), h: Math.max(1, maxY - minY)};
    },
    buildPolyMaskData(polyPts, w, h, offX, offY, invert) {
      const mask = document.createElement('canvas');
      mask.width = w;
      mask.height = h;
      const mctx = mask.getContext('2d');
      if (invert) {
        mctx.fillStyle = '#fff';
        mctx.fillRect(0, 0, w, h);
        mctx.globalCompositeOperation = 'destination-out';
      } else {
        mctx.fillStyle = '#fff';
      }
      mctx.beginPath();
      mctx.moveTo(polyPts[0].x - offX, polyPts[0].y - offY);
      for (let i = 1; i < polyPts.length; i++) {
        mctx.lineTo(polyPts[i].x - offX, polyPts[i].y - offY);
      }
      mctx.closePath();
      mctx.fill();
      mctx.globalCompositeOperation = 'source-over';
      const rawData = mctx.getImageData(0, 0, w, h).data;
      const alpha = new Uint8Array(w * h);
      for (let i = 0; i < w * h; i++) {
        alpha[i] = rawData[i * 4 + 3] > 127 ? 1 : 0;
      }
      return alpha;
    },
    clipPolyFromLayerPrecise(layer, polyPts) {
      const {minX, minY, maxX, maxY, w: bw, h: bh} = this.calcPolyBounds(polyPts);
      const lc = layer.canvas;
      const lctx = lc.getContext('2d');
      const clip = document.createElement('canvas');
      clip.width = bw;
      clip.height = bh;
      const cctx = clip.getContext('2d');
      const fullImg = lctx.getImageData(0, 0, lc.width, lc.height);
      const fullData = new Uint32Array(fullImg.data.buffer);
      const clipImg = cctx.createImageData(bw, bh);
      const clipData = new Uint32Array(clipImg.data.buffer);
      const maskAlpha = this.buildPolyMaskData(polyPts, bw, bh, minX, minY, false);
      const eraseMask = new Uint8Array(lc.width * lc.height);
      for (let cy = 0; cy < bh; cy++) {
        const docY = minY + cy;
        const layerY = docY - layer.y;
        if (layerY < 0 || layerY >= lc.height) continue;
        for (let cx = 0; cx < bw; cx++) {
          if (maskAlpha[cy * bw + cx]) {
            const docX = minX + cx;
            const layerX = docX - layer.x;
            if (layerX >= 0 && layerX < lc.width) {
              const srcIdx = layerY * lc.width + layerX;
              clipData[cy * bw + cx] = fullData[srcIdx];
              eraseMask[srcIdx] = 1;
            }
          }
        }
      }
      cctx.putImageData(clipImg, 0, 0);
      for (let i = 0; i < fullData.length; i++) {
        if (eraseMask[i]) {
          fullData[i] = 0;
        }
      }
      lctx.putImageData(fullImg, 0, 0);
      return {clip, minX, minY, maxX, maxY, bw, bh};
    },
    finalizeLasso() {
      const draft = this.lassoDraft;
      this.lassoDraft = null;
      if (!draft || draft.points.length < 3) {
        this.renderAll();
        return;
      }
      const layer = this.activeLayer;
      if (!layer) {
        this.renderAll();
        return;
      }
      const pts = draft.points.map(p => ({
        x: Math.max(0, Math.min(this.docWidth, p.x)),
        y: Math.max(0, Math.min(this.docHeight, p.y))
      }));
      // 在剪切像素前快照：撤销套索 = 恢复完整像素并取消选区
      this.pushHistory();
      const r = this.clipPolyFromLayerPrecise(layer, pts);
      this.selection = {
        points: pts,
        bounds: {minX: r.minX, minY: r.minY, maxX: r.maxX, maxY: r.maxY, w: r.bw, h: r.bh},
        image: r.clip,
        x: r.minX,
        y: r.minY,
        layerId: layer.id,
        committed: false
      };
      this.renderAll();
    },
    // 矩形/椭圆套索闭合：把拖动区域转为多边形点集，复用 clipPolyFromLayerPrecise
    finalizeShapeLasso() {
      const draft = this.shapeDraft;
      this.shapeDraft = null;
      if (!draft) {
        this.renderAll();
        return;
      }
      const layer = this.activeLayer;
      if (!layer) {
        this.renderAll();
        return;
      }
      const s = draft.start, e = draft.end;
      const minX = Math.max(0, Math.min(s.x, e.x));
      const minY = Math.max(0, Math.min(s.y, e.y));
      const maxX = Math.min(this.docWidth, Math.max(s.x, e.x));
      const maxY = Math.min(this.docHeight, Math.max(s.y, e.y));
      if (maxX - minX < 2 || maxY - minY < 2) {
        this.renderAll();
        return;
      }
      let pts;
      if (draft.shape === 'rect') {
        pts = [
          {x: minX, y: minY},
          {x: maxX, y: minY},
          {x: maxX, y: maxY},
          {x: minX, y: maxY}
        ];
      } else {
        pts = this.genEllipsePoints(minX, minY, maxX, maxY);
      }
      this.pushHistory();
      const r = this.clipPolyFromLayerPrecise(layer, pts);
      this.selection = {
        points: pts,
        bounds: {minX: r.minX, minY: r.minY, maxX: r.maxX, maxY: r.maxY, w: r.bw, h: r.bh},
        image: r.clip,
        x: r.minX,
        y: r.minY,
        layerId: layer.id,
        committed: false
      };
      this.renderAll();
    },
    // 生成椭圆边界多边形点集
    genEllipsePoints(minX, minY, maxX, maxY) {
      const cx = (minX + maxX) / 2;
      const cy = (minY + maxY) / 2;
      const rx = (maxX - minX) / 2;
      const ry = (maxY - minY) / 2;
      const pts = [];
      const n = 64;
      for (let i = 0; i < n; i++) {
        const a = (i / n) * Math.PI * 2;
        pts.push({
          x: cx + rx * Math.cos(a),
          y: cy + ry * Math.sin(a)
        });
      }
      return pts;
    },
    commitSelectionMove() {
      const sel = this.selection;
      if (!sel || !sel.image) return;
      const layer = this.layers.find(l => l.id === sel.layerId);
      if (!layer) return;
      const lctx = layer.canvas.getContext('2d');
      const clipImg = sel.image.getContext('2d').getImageData(0, 0, sel.image.width, sel.image.height);
      const clipData = new Uint32Array(clipImg.data.buffer);
      const bw = sel.image.width, bh = sel.image.height;
      const fullImg = lctx.getImageData(0, 0, layer.canvas.width, layer.canvas.height);
      const fullData = new Uint32Array(fullImg.data.buffer);
      for (let cy = 0; cy < bh; cy++) {
        for (let cx = 0; cx < bw; cx++) {
          const px = clipData[cy * bw + cx];
          const alpha = (px >>> 24) & 0xff;
          if (alpha > 0) {
            const docX = sel.x + cx;
            const docY = sel.y + cy;
            const layerX = docX - layer.x;
            const layerY = docY - layer.y;
            if (layerX >= 0 && layerX < layer.canvas.width && layerY >= 0 && layerY < layer.canvas.height) {
              fullData[layerY * layer.canvas.width + layerX] = px;
            }
          }
        }
      }
      lctx.putImageData(fullImg, 0, 0);
      const oldMinX = sel.bounds.minX, oldMinY = sel.bounds.minY;
      const dx = sel.x - oldMinX, dy = sel.y - oldMinY;
      sel.bounds.minX = sel.x;
      sel.bounds.minY = sel.y;
      for (const p of sel.points) { p.x += dx; p.y += dy; }
      sel.committed = true;
      this.renderAll();
    },
    // 清空选区：若有未提交的浮动像素，先写回图层再取消（避免丢像素）
    clearSelection() {
      const sel = this.selection;
      if (sel && !sel.committed && sel.image) {
        this.commitSelectionMove();
      }
      this.selection = null;
    },
    /* ========== 套索选区右键菜单 ========== */
    onWindowClick() {
      // 点击页面任意位置关闭选区/裁剪菜单
      if (this.selMenu.visible) this.closeSelMenu();
      if (this.cropMenu.visible) this.closeCropMenu();
    },
    onCanvasContextMenu(e) {
      // 裁剪模式下右键：弹出裁剪操作菜单
      if (this.tool === 'cropImage' && this.crop) {
        this.cropMenu = {visible: true, x: e.clientX, y: e.clientY};
        return;
      }
      // 右键：若有选区，弹出选区操作菜单；否则不阻止默认行为外的其他逻辑
      if (this.selection) {
        this.showSelectionMenu(e);
      }
    },
    showSelectionMenu(e) {
      // 在画布内右键 + 当前有选区 → 弹出选区操作菜单
      if (!this.selection) return false;
      const pos = this.getDocPos(e);
      this.selMenu = {
        visible: true,
        x: e.clientX,
        y: e.clientY,
        inSelection: this.pointInSelection(pos)
      };
      return true;
    },
    closeSelMenu() {
      this.selMenu.visible = false;
    },
    closeCropMenu() {
      this.cropMenu.visible = false;
    },
    selMenuInSelection() {
      return this.selMenu.visible && this.selMenu.inSelection;
    },
    /* ========== 选区操作：删除 ========== */
    erasePolyFromLayerPrecise(layer, polyPts) {
      const lc = layer.canvas;
      const lctx = lc.getContext('2d');
      const fullImg = lctx.getImageData(0, 0, lc.width, lc.height);
      const fullData = new Uint32Array(fullImg.data.buffer);
      const {minX, minY, maxX, maxY, w: bw, h: bh} = this.calcPolyBounds(polyPts);
      const maskAlpha = this.buildPolyMaskData(polyPts, bw, bh, minX, minY, false);
      for (let cy = 0; cy < bh; cy++) {
        const docY = minY + cy;
        const layerY = docY - layer.y;
        if (layerY < 0 || layerY >= lc.height) continue;
        for (let cx = 0; cx < bw; cx++) {
          if (maskAlpha[cy * bw + cx]) {
            const docX = minX + cx;
            const layerX = docX - layer.x;
            if (layerX >= 0 && layerX < lc.width) {
              fullData[layerY * lc.width + layerX] = 0;
            }
          }
        }
      }
      lctx.putImageData(fullImg, 0, 0);
    },
    fillPolyOnLayerPrecise(layer, polyPts, rgba) {
      const lc = layer.canvas;
      const lctx = lc.getContext('2d');
      const fullImg = lctx.getImageData(0, 0, lc.width, lc.height);
      const fullData = new Uint32Array(fullImg.data.buffer);
      const {minX, minY, maxX, maxY, w: bw, h: bh} = this.calcPolyBounds(polyPts);
      const maskAlpha = this.buildPolyMaskData(polyPts, bw, bh, minX, minY, false);
      for (let cy = 0; cy < bh; cy++) {
        const docY = minY + cy;
        const layerY = docY - layer.y;
        if (layerY < 0 || layerY >= lc.height) continue;
        for (let cx = 0; cx < bw; cx++) {
          if (maskAlpha[cy * bw + cx]) {
            const docX = minX + cx;
            const layerX = docX - layer.x;
            if (layerX >= 0 && layerX < lc.width) {
              fullData[layerY * lc.width + layerX] = rgba;
            }
          }
        }
      }
      lctx.putImageData(fullImg, 0, 0);
    },
    fillOutsidePolyOnLayerPrecise(layer, innerPts, rgba) {
      const lc = layer.canvas;
      const lctx = lc.getContext('2d');
      const fullImg = lctx.getImageData(0, 0, lc.width, lc.height);
      const fullData = new Uint32Array(fullImg.data.buffer);
      const dw = this.docWidth, dh = this.docHeight;
      const maskAlpha = this.buildPolyMaskData(innerPts, dw, dh, 0, 0, true);
      for (let ly = 0; ly < lc.height; ly++) {
        for (let lx = 0; lx < lc.width; lx++) {
          const docX = lx + layer.x;
          const docY = ly + layer.y;
          if (docX >= 0 && docX < dw && docY >= 0 && docY < dh) {
            if (maskAlpha[docY * dw + docX]) {
              fullData[ly * lc.width + lx] = rgba;
            }
          }
        }
      }
      lctx.putImageData(fullImg, 0, 0);
    },
    deleteSelection() {
      const sel = this.selection;
      if (!sel || !sel.points || sel.points.length < 3) return;
      this.pushHistory();
      this.selection = null;
      this.renderAll();
    },
    /* ========== 选区操作：反选 ========== */
    clipOutsidePolyFromLayerPrecise(layer, innerPts) {
      const lc = layer.canvas;
      const bw = lc.width;
      const bh = lc.height;
      const lctx = lc.getContext('2d');
      const dw = this.docWidth, dh = this.docHeight;
      const maskAlpha = this.buildPolyMaskData(innerPts, dw, dh, 0, 0, true);
      const fullImg = lctx.getImageData(0, 0, bw, bh);
      const fullData = new Uint32Array(fullImg.data.buffer);
      const clip = document.createElement('canvas');
      clip.width = dw;
      clip.height = dh;
      const cctx = clip.getContext('2d');
      const clipImg = cctx.createImageData(dw, dh);
      const clipData = new Uint32Array(clipImg.data.buffer);
      for (let ly = 0; ly < bh; ly++) {
        for (let lx = 0; lx < bw; lx++) {
          const docX = lx + layer.x;
          const docY = ly + layer.y;
          if (docX >= 0 && docX < dw && docY >= 0 && docY < dh) {
            if (maskAlpha[docY * dw + docX]) {
              const srcIdx = ly * bw + lx;
              clipData[docY * dw + docX] = fullData[srcIdx];
              fullData[srcIdx] = 0;
            }
          }
        }
      }
      cctx.putImageData(clipImg, 0, 0);
      lctx.putImageData(fullImg, 0, 0);
      return {clip, minX: 0, minY: 0, maxX: dw, maxY: dh, bw: dw, bh: dh};
    },
    invertSelection() {
      const sel = this.selection;
      if (!sel || !sel.points || sel.points.length < 3) return;
      const layer = this.layers.find(l => l.id === sel.layerId);
      if (!layer) return;
      this.pushHistory();
      if (sel.inverted && sel.originalPoints) {
        if (!sel.committed && sel.image) {
          this.commitSelectionMove();
        }
        const origPts = sel.originalPoints;
        const r = this.clipPolyFromLayerPrecise(layer, origPts);
        this.selection = {
          points: origPts,
          bounds: {minX: r.minX, minY: r.minY, maxX: r.maxX, maxY: r.maxY, w: r.bw, h: r.bh},
          image: r.clip,
          x: r.minX,
          y: r.minY,
          layerId: layer.id,
          committed: false,
          inverted: false,
          originalPoints: null
        };
        this.renderAll();
        return;
      }
      if (!sel.committed && sel.image) {
        this.commitSelectionMove();
      }
      const originalPoints = sel.points.map(p => ({x: p.x, y: p.y}));
      const borderPts = [
        {x: 0, y: 0},
        {x: this.docWidth, y: 0},
        {x: this.docWidth, y: this.docHeight},
        {x: 0, y: this.docHeight}
      ];
      const r = this.clipOutsidePolyFromLayerPrecise(layer, originalPoints);
      this.selection = {
        points: borderPts,
        bounds: {minX: 0, minY: 0, maxX: this.docWidth, maxY: this.docHeight, w: this.docWidth, h: this.docHeight},
        image: r.clip,
        x: 0,
        y: 0,
        layerId: layer.id,
        committed: false,
        inverted: true,
        originalPoints: originalPoints
      };
      this.renderAll();
    },
    /* ========== 选区操作：填充 ========== */
    fillSelection() {
      const sel = this.selection;
      if (!sel || !sel.points || sel.points.length < 3) return;
      const layer = this.layers.find(l => l.id === sel.layerId);
      if (!layer) return;
      this.pushHistory();
      if (!sel.committed && sel.image) {
        this.commitSelectionMove();
      }
      const rgb = this.hexToRgb(this.color);
      const fillVal = (255 << 24) | (rgb.b << 16) | (rgb.g << 8) | rgb.r;
      if (sel.inverted && sel.originalPoints) {
        this.fillOutsidePolyOnLayerPrecise(layer, sel.originalPoints, fillVal);
      } else {
        this.fillPolyOnLayerPrecise(layer, sel.points, fillVal);
      }
      // 填充结果直接落在图层上：黑色就是不透明黑、透明仍是透明，
      // 显示/导出/面板信息完全一致；选区只保留蚂蚁线，不再剪回浮动层，
      // 后续移动/拷贝/自由变换会通过 ensureSelectionFloating 按需重新剪切
      sel.image = null;
      sel.committed = true;
      this.renderAll();
    },
    // 选区只有蚂蚁线（无浮动像素）时，从图层重新剪切内容到浮动层，
    // 供移动/拷贝/自由变换使用；剪切语义与套索闭合一致
    ensureSelectionFloating() {
      const sel = this.selection;
      if (!sel || sel.image || !sel.points || sel.points.length < 3) return;
      const layer = this.layers.find(l => l.id === sel.layerId);
      if (!layer) return;
      let r;
      if (sel.inverted && sel.originalPoints) {
        r = this.clipOutsidePolyFromLayerPrecise(layer, sel.originalPoints);
      } else {
        r = this.clipPolyFromLayerPrecise(layer, sel.points);
      }
      sel.image = r.clip;
      sel.bounds = {minX: r.minX, minY: r.minY, maxX: r.maxX, maxY: r.maxY, w: r.bw, h: r.bh};
      sel.x = r.minX;
      sel.y = r.minY;
      sel.committed = false;
    },
    /* ========== 选区操作：拷贝 ========== */
    copySelection() {
      const sel = this.selection;
      if (!sel) return;
      // 填充后选区只有蚂蚁线：先从图层重新剪切出浮动像素
      this.ensureSelectionFloating();
      if (!sel.image) return;
      // 先写回图层，再从图层提取像素到剪贴板，然后立即切掉图层上的对应像素（保持剪切语义）
      this.commitSelectionMove();
      this.clipboard = {
        image: sel.image,
        w: sel.bounds.w,
        h: sel.bounds.h
      };
    },
    /* ========== 选区操作：粘贴 ========== */
    pasteFromClipboard() {
      if (!this.clipboard || !this.clipboard.image) return;
      // 创建新图层承载粘贴内容
      const layer = this.makeLayer('粘贴');
      this.layers.push(layer);
      this.activeLayerId = layer.id;
      const lctx = layer.canvas.getContext('2d');
      lctx.drawImage(this.clipboard.image, 0, 0);
      this.pushHistory();
      this.$nextTick(() => this.renderAll());
    },
    /* ========== 选区操作：自由变换 ========== */
    freeTransformStart() {
      const sel = this.selection;
      if (!sel) return;
      // 填充后选区只有蚂蚁线：先从图层重新剪切出浮动像素
      this.ensureSelectionFloating();
      if (!sel.image) return;
      // 先把浮动选区写回原剪切位置（保持选区当前位置为变换基准）
      // origImage 保留原始尺寸；x/y/w/h 是变换框当前显示位置和尺寸
      const ow = sel.bounds.w, oh = sel.bounds.h;
      this.transform = {
        origImage: sel.image,
        origX: sel.x,
        origY: sel.y,
        origW: ow,
        origH: oh,
        x: sel.x,
        y: sel.y,
        w: ow,
        h: oh,
        handle: null  // 当前拖动的手柄 id，null 表示未在拖动
      };
    },
    // 8 个手柄位置（相对于变换框），返回画布坐标
    transformHandles() {
      const t = this.transform;
      if (!t) return [];
      const x = t.x, y = t.y, w = t.w, h = t.h;
      return [
        {id: 'nw', x: x,         y: y},
        {id: 'n',  x: x + w / 2, y: y},
        {id: 'ne', x: x + w,     y: y},
        {id: 'e',  x: x + w,     y: y + h / 2},
        {id: 'se', x: x + w,     y: y + h},
        {id: 's',  x: x + w / 2, y: y + h},
        {id: 'sw', x: x,         y: y + h},
        {id: 'w',  x: x,         y: y + h / 2}
      ];
    },
    // 检测鼠标是否落在某手柄上，返回手柄 id 或 null
    hitTransformHandle(pos) {
      const t = this.transform;
      if (!t) return null;
      const r = 8 / this.zoom; // 手柄检测半径，屏幕上 8px
      for (const h of this.transformHandles()) {
        const dx = pos.x - h.x, dy = pos.y - h.y;
        if (dx * dx + dy * dy <= r * r) return h.id;
      }
      return null;
    },
    // 应用变换：根据当前 transform 框重新绘制选区内容到 selection.image
    applyTransform() {
      const t = this.transform;
      if (!t) return;
      const sel = this.selection;
      if (!sel) return;
      // 缩放后的图像
      const scaled = document.createElement('canvas');
      scaled.width = Math.max(1, Math.round(t.w));
      scaled.height = Math.max(1, Math.round(t.h));
      const sctx = scaled.getContext('2d');
      sctx.imageSmoothingEnabled = true;
      sctx.drawImage(t.origImage, 0, 0, scaled.width, scaled.height);
      sel.image = scaled;
      sel.x = Math.round(t.x);
      sel.y = Math.round(t.y);
      sel.bounds.w = scaled.width;
      sel.bounds.h = scaled.height;
      sel.bounds.minX = sel.x;
      sel.bounds.minY = sel.y;
      sel.bounds.maxX = sel.x + scaled.width;
      sel.bounds.maxY = sel.y + scaled.height;
      this.renderAll();
    },
    commitTransform() {
      // 确认变换：把缩放后的选区写回图层
      if (!this.transform) return;
      // 在应用变换前快照：撤销变换 = 恢复变换前的选区尺寸/位置
      this.pushHistory();
      this.applyTransform();
      this.transform = null;
      this.renderAll();
    },
    cancelTransform() {
      // 取消变换：还原 selection 到变换前的状态
      const t = this.transform;
      if (!t) return;
      const sel = this.selection;
      if (sel) {
        sel.image = t.origImage;
        sel.x = t.origX;
        sel.y = t.origY;
        sel.bounds.w = t.origW;
        sel.bounds.h = t.origH;
        sel.bounds.minX = t.origX;
        sel.bounds.minY = t.origY;
        sel.bounds.maxX = t.origX + t.origW;
        sel.bounds.maxY = t.origY + t.origH;
      }
      this.transform = null;
      this.renderAll();
    },
    /* ========== 裁剪 ========== */
    // 裁剪框的 8 个手柄（4 角 + 4 边中点），与自由变换同一套交互
    cropHandles() {
      const c = this.crop;
      if (!c) return [];
      const x = c.x, y = c.y, w = c.w, h = c.h;
      return [
        {id: 'nw', x: x,         y: y},
        {id: 'n',  x: x + w / 2, y: y},
        {id: 'ne', x: x + w,     y: y},
        {id: 'e',  x: x + w,     y: y + h / 2},
        {id: 'se', x: x + w,     y: y + h},
        {id: 's',  x: x + w / 2, y: y + h},
        {id: 'sw', x: x,         y: y + h},
        {id: 'w',  x: x,         y: y + h / 2}
      ];
    },
    // 检测鼠标是否落在某裁剪手柄上，返回手柄 id 或 null
    hitCropHandle(pos) {
      if (!this.crop) return null;
      const r = 8 / this.zoom; // 手柄检测半径，屏幕上 8px
      for (const h of this.cropHandles()) {
        const dx = pos.x - h.x, dy = pos.y - h.y;
        if (dx * dx + dy * dy <= r * r) return h.id;
      }
      return null;
    },
    // 裁剪工具按下：命中手柄 → 拖边缘/角点；框内 → 整体移动；框外 → 拖出新框
    startCropDrag(pos) {
      const c = this.crop;
      if (c) {
        const handle = this.hitCropHandle(pos);
        if (handle) {
          this.dragState = {
            mode: 'cropScale',
            handle,
            startDoc: pos,
            orig: {x: c.x, y: c.y, w: c.w, h: c.h}
          };
          this.bindWindowDrag();
          return;
        }
        if (pos.x >= c.x && pos.x <= c.x + c.w &&
            pos.y >= c.y && pos.y <= c.y + c.h) {
          this.dragState = {mode: 'cropMove', startDoc: pos, orig: {x: c.x, y: c.y}};
          this.bindWindowDrag();
          return;
        }
      }
      const sx = Math.max(0, Math.min(this.docWidth, pos.x));
      const sy = Math.max(0, Math.min(this.docHeight, pos.y));
      this.crop = {x: sx, y: sy, w: 0, h: 0};
      this.dragState = {mode: 'cropNew', start: {x: sx, y: sy}};
      this.bindWindowDrag();
      this.renderAll();
    },
    // 确认裁剪：文档收缩到裁剪框，所有图层随之平移（图层像素保留，可撤销）
    commitCrop() {
      const c = this.crop;
      if (!c) return;
      // 裁剪框与文档取交集
      const x = Math.max(0, Math.round(c.x));
      const y = Math.max(0, Math.round(c.y));
      const x2 = Math.min(this.docWidth, Math.round(c.x + c.w));
      const y2 = Math.min(this.docHeight, Math.round(c.y + c.h));
      if (x2 - x < 1 || y2 - y < 1) {
        this.cancelCrop();
        return;
      }
      // 裁剪框覆盖整个文档 → 无需裁剪，直接退出
      if (x === 0 && y === 0 && x2 === this.docWidth && y2 === this.docHeight) {
        this.crop = null;
        this.renderAll();
        return;
      }
      this.pushHistory();
      // 有未提交的浮动选区像素时先写回图层，避免裁剪丢像素
      this.clearSelection();
      for (const l of this.layers) {
        l.x -= x;
        l.y -= y;
      }
      this.docWidth = x2 - x;
      this.docHeight = y2 - y;
      this.crop = null;
      this.renderAll();
    },
    cancelCrop() {
      if (!this.crop) return;
      this.crop = null;
      this.renderAll();
    },
    // 选区右键「裁剪」：直接按选区边界框裁剪文档
    cropToSelection() {
      const sel = this.selection;
      if (!sel || !sel.points || sel.points.length < 3) return;
      // 反选状态下仍按原始选区的边界框裁剪
      const pts = (sel.inverted && sel.originalPoints) ? sel.originalPoints : sel.points;
      const b = this.calcPolyBounds(pts);
      // 写回未提交的浮动像素并取消选区
      this.clearSelection();
      const x = Math.max(0, b.minX);
      const y = Math.max(0, b.minY);
      const x2 = Math.min(this.docWidth, b.maxX);
      const y2 = Math.min(this.docHeight, b.maxY);
      if (x2 - x < 1 || y2 - y < 1) return;
      this.crop = {x, y, w: x2 - x, h: y2 - y};
      this.commitCrop();
    },
    strokeTo(ctx, from, to) {
      ctx.save();
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.lineWidth = this.size;
      if (this.tool === 'eraser') {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.strokeStyle = 'rgba(0,0,0,1)';
      } else {
        ctx.strokeStyle = this.color;
      }
      ctx.beginPath();
      ctx.moveTo(from.x, from.y);
      ctx.lineTo(to.x, to.y);
      ctx.stroke();
      ctx.restore();
    },
    drawShape(ctx, from, to) {
      ctx.save();
      ctx.lineWidth = this.size;
      ctx.strokeStyle = this.color;
      ctx.fillStyle = this.color;
      ctx.beginPath();
      if (this.tool === 'line') {
        ctx.moveTo(from.x, from.y);
        ctx.lineTo(to.x, to.y);
        ctx.stroke();
      } else if (this.tool === 'rect') {
        const x = Math.min(from.x, to.x), y = Math.min(from.y, to.y);
        const w = Math.abs(to.x - from.x), h = Math.abs(to.y - from.y);
        if (this.shapeFill) ctx.fillRect(x, y, w, h);
        else ctx.strokeRect(x, y, w, h);
      } else if (this.tool === 'ellipse') {
        const cx = (from.x + to.x) / 2, cy = (from.y + to.y) / 2;
        ctx.ellipse(cx, cy, Math.abs(to.x - from.x) / 2, Math.abs(to.y - from.y) / 2, 0, 0, Math.PI * 2);
        if (this.shapeFill) ctx.fill();
        else ctx.stroke();
      }
      ctx.restore();
    },
    floodFill(layer, pos) {
      const c = layer.canvas;
      const x = Math.floor(pos.x - layer.x), y = Math.floor(pos.y - layer.y);
      if (x < 0 || y < 0 || x >= c.width || y >= c.height) return;
      const ctx = c.getContext('2d');
      const img = ctx.getImageData(0, 0, c.width, c.height);
      const data = new Uint32Array(img.data.buffer);
      const w = c.width, h = c.height;
      const target = data[y * w + x];
      const rgb = this.hexToRgb(this.color);
      const fill = (255 << 24) | (rgb.b << 16) | (rgb.g << 8) | rgb.r;
      if (target === fill) return;
      const stack = [y * w + x];
      while (stack.length) {
        const i = stack.pop();
        if (data[i] !== target) continue;
        data[i] = fill;
        const px = i % w, py = Math.floor(i / w);
        if (px > 0) stack.push(i - 1);
        if (px < w - 1) stack.push(i + 1);
        if (py > 0) stack.push(i - w);
        if (py < h - 1) stack.push(i + w);
      }
      // 若存在套索选区，则把填充结果与选区遮罩做 AND：选区外的像素还原
      const sel = this.selection;
      if (sel && sel.points && sel.points.length >= 3) {
        const selMask = document.createElement('canvas');
        selMask.width = w; selMask.height = h;
        const smctx = selMask.getContext('2d');
        smctx.fillStyle = '#fff';
        smctx.beginPath();
        smctx.moveTo(sel.points[0].x - layer.x, sel.points[0].y - layer.y);
        for (let k = 1; k < sel.points.length; k++) {
          smctx.lineTo(sel.points[k].x - layer.x, sel.points[k].y - layer.y);
        }
        smctx.closePath();
        smctx.fill();
        const mimg = smctx.getImageData(0, 0, w, h);
        const mdata = new Uint32Array(mimg.data.buffer);
        for (let i = 0; i < data.length; i++) {
          // 选区外 alpha=0 → 还原为原 target
          if ((mdata[i] >>> 24) === 0) data[i] = target;
        }
      }
      ctx.putImageData(img, 0, 0);
    },
    pickColor(pos) {
      const x = Math.floor(pos.x), y = Math.floor(pos.y);
      if (x < 0 || y < 0 || x >= this.docWidth || y >= this.docHeight) return;
      const ctx = this.$refs.mainCanvas.getContext('2d');
      const d = ctx.getImageData(x, y, 1, 1).data;
      this.color = this.rgbToHex(d[0], d[1], d[2]);
    },
    confirmText() {
      const layer = this.activeLayer;
      const isEdit = this.textModal.isEdit;
      this.textModal.visible = false;
      if (!this.textModal.content) {
        // 编辑时清空内容 = 取消该浮动文字
        if (isEdit) this.floatingText = null;
        return;
      }
      if (!layer) return;
      this.fontSize = this.textModal.size;
      // 测量文字尺寸，用于后续判断鼠标点击是否落在文字范围内
      const measureCanvas = document.createElement('canvas');
      const mctx = measureCanvas.getContext('2d');
      mctx.font = this.textModal.size + 'px "Microsoft YaHei", sans-serif';
      const metrics = mctx.measureText(this.textModal.content);
      const width = Math.max(1, Math.ceil(metrics.width));
      const height = Math.max(1, Math.ceil(this.textModal.size * 1.2));
      if (isEdit && this.floatingText) {
        // 重新编辑：更新内容/字号/颜色，位置保持不变
        this.floatingText.content = this.textModal.content;
        this.floatingText.size = this.textModal.size;
        this.floatingText.color = this.textModal.color;
        this.floatingText.width = width;
        this.floatingText.height = height;
      } else {
        // 文字进入浮动状态：未绘制到图层，可拖动；保存后才固定
        this.floatingText = {
          content: this.textModal.content,
          size: this.textModal.size,
          color: this.textModal.color,
          x: this.textModal.x,
          y: this.textModal.y,
          width: width,
          height: height
        };
      }
      this.renderAll();
    },
    // 打开弹窗重新编辑当前浮动文字
    editFloatingText() {
      const ft = this.floatingText;
      if (!ft) return;
      this.textModal = {
        visible: true,
        content: ft.content,
        size: ft.size,
        color: ft.color,
        x: ft.x,
        y: ft.y,
        isEdit: true
      };
    },
    /* ========== 浮动文字：保存 / 取消 ========== */
    switchTool(id) {
      // 切换工具前若有未保存的浮动文字，先固定到当前图层，避免丢失
      if (this.floatingText && id !== 'text') {
        this.commitText();
      }
      // 切换工具前若处于自由变换模式，先确认变换
      if (this.transform) {
        this.commitTransform();
      }
      // 切离裁剪工具时丢弃未确认的裁剪框
      if (this.crop && id !== 'cropImage') {
        this.crop = null;
        this.cropMenu.visible = false;
        this.renderAll();
      }
      // 选中裁剪工具：默认裁剪框铺满整个文档，手柄直接出现在图片边缘
      if (id === 'cropImage' && !this.crop) {
        this.crop = {x: 0, y: 0, w: this.docWidth, h: this.docHeight};
        this.renderAll();
      }
      // 切换到套索工具外的工具时，若有未提交的选区内容，自动写回图层
      if (this.selection && id !== 'lasso' && id !== 'rectLasso' && id !== 'ellipseLasso' && id !== 'move') {
        this.commitSelectionMove();
        this.selection = null;
        this.renderAll();
      }
      this.tool = id;
    },
    commitText() {
      const ft = this.floatingText;
      const layer = this.activeLayer;
      if (!ft || !layer) {
        this.floatingText = null;
        return;
      }
      this.pushHistory();
      const ctx = layer.canvas.getContext('2d');
      ctx.save();
      ctx.font = ft.size + 'px "Microsoft YaHei", sans-serif';
      ctx.fillStyle = ft.color;
      ctx.textBaseline = 'top';
      ctx.fillText(ft.content, ft.x - layer.x, ft.y - layer.y);
      ctx.restore();
      this.floatingText = null;
      this.renderAll();
    },
    cancelText() {
      this.floatingText = null;
      this.renderAll();
    },
    hitFloatingText(pos) {
      const ft = this.floatingText;
      if (!ft) return false;
      return pos.x >= ft.x && pos.x <= ft.x + ft.width &&
             pos.y >= ft.y && pos.y <= ft.y + ft.height;
    },
    /* ========== 图层操作 ========== */
    addLayer() {
      this.pushHistory();
      const layer = this.makeLayer('图层 ' + (++this.layerNameSeq));
      this.layers.push(layer);
      this.activeLayerId = layer.id;
      this.renderAll();
    },
    dupLayer() {
      const layer = this.activeLayer;
      if (!layer) return;
      this.pushHistory();
      const copy = {
        id: ++this.idSeq,
        name: layer.name + ' 副本',
        visible: layer.visible,
        opacity: layer.opacity,
        x: layer.x,
        y: layer.y,
        rotation: layer.rotation,
        canvas: this.cloneCanvas(layer.canvas)
      };
      const idx = this.layers.indexOf(layer);
      this.layers.splice(idx + 1, 0, copy);
      this.activeLayerId = copy.id;
      this.renderAll();
    },
    deleteLayer() {
      const layer = this.activeLayer;
      if (!layer) return;
      this.pushHistory();
      if (this.layers.length > 1) {
        const idx = this.layers.indexOf(layer);
        this.layers.splice(idx, 1);
        this.activeLayerId = this.layers[Math.max(0, idx - 1)].id;
      } else {
        layer.canvas.getContext('2d').clearRect(0, 0, layer.canvas.width, layer.canvas.height);
        layer.x = 0;
        layer.y = 0;
        layer.rotation = 0;
      }
      this.renderAll();
    },
    layerUp() {
      const idx = this.layers.findIndex(l => l.id === this.activeLayerId);
      if (idx < 0 || idx >= this.layers.length - 1) return;
      this.pushHistory();
      const tmp = this.layers[idx];
      this.layers.splice(idx, 1, this.layers[idx + 1]);
      this.layers.splice(idx + 1, 1, tmp);
      this.renderAll();
    },
    layerDown() {
      const idx = this.layers.findIndex(l => l.id === this.activeLayerId);
      if (idx <= 0) return;
      this.pushHistory();
      const tmp = this.layers[idx];
      this.layers.splice(idx, 1, this.layers[idx - 1]);
      this.layers.splice(idx - 1, 1, tmp);
      this.renderAll();
    },
    mergeDown() {
      const idx = this.layers.findIndex(l => l.id === this.activeLayerId);
      if (idx <= 0) return;
      this.pushHistory();
      const top = this.layers[idx];
      const below = this.layers[idx - 1];
      const ctx = below.canvas.getContext('2d');
      ctx.save();
      ctx.globalAlpha = top.opacity / 100;
      const w = top.canvas.width, h = top.canvas.height;
      ctx.translate(top.x + w / 2, top.y + h / 2);
      ctx.rotate(top.rotation * Math.PI / 180);
      ctx.drawImage(top.canvas, -w / 2, -h / 2);
      ctx.restore();
      this.layers.splice(idx, 1);
      this.activeLayerId = below.id;
      this.renderAll();
    },
    toggleLayerVisible(l) {
      l.visible = !l.visible;
      this.renderAll();
    },
    /* ========== 图片操作 ========== */
    confirmSize() {
      const w = Math.max(1, Math.min(5000, Math.round(this.sizeModal.width || 800)));
      const h = Math.max(1, Math.min(5000, Math.round(this.sizeModal.height || 600)));
      const mode = this.sizeModal.mode;
      this.sizeModal.visible = false;
      this.pushHistory();
      if (mode === 'new') {
        this.docWidth = w;
        this.docHeight = h;
        this.layerNameSeq = 1;
        this.layers = [this.makeLayer('背景')];
        this.activeLayerId = this.layers[0].id;
      } else {
        for (const l of this.layers) {
          const c = document.createElement('canvas');
          c.width = w;
          c.height = h;
          c.getContext('2d').drawImage(l.canvas, 0, 0, w, h);
          l.canvas = c;
          l.x = 0;
          l.y = 0;
        }
        this.docWidth = w;
        this.docHeight = h;
      }
      this.renderAll();
    },
    flipDoc(dir) {
      this.pushHistory();
      for (const l of this.layers) {
        const c = l.canvas;
        const tmp = this.cloneCanvas(c);
        const ctx = c.getContext('2d');
        ctx.clearRect(0, 0, c.width, c.height);
        ctx.save();
        if (dir === 'h') {
          ctx.translate(c.width, 0);
          ctx.scale(-1, 1);
        } else {
          ctx.translate(0, c.height);
          ctx.scale(1, -1);
        }
        ctx.drawImage(tmp, 0, 0);
        ctx.restore();
        if (dir === 'h') l.x = this.docWidth - l.x - c.width;
        else l.y = this.docHeight - l.y - c.height;
      }
      this.renderAll();
    },
    rotateDoc90() {
      this.pushHistory();
      const flat = document.createElement('canvas');
      flat.width = this.docWidth;
      flat.height = this.docHeight;
      this.compositeTo(flat.getContext('2d'));
      const nw = this.docHeight, nh = this.docWidth;
      this.docWidth = nw;
      this.docHeight = nh;
      const layer = this.makeLayer('旋转结果');
      const ctx = layer.canvas.getContext('2d');
      ctx.translate(nw / 2, nh / 2);
      ctx.rotate(Math.PI / 2);
      ctx.drawImage(flat, -flat.width / 2, -flat.height / 2);
      this.layers = [layer];
      this.activeLayerId = layer.id;
      this.renderAll();
    },
    clearCanvas() {
      this.pushHistory();
      for (const l of this.layers) {
        l.canvas.getContext('2d').clearRect(0, 0, l.canvas.width, l.canvas.height);
        l.x = 0;
        l.y = 0;
        l.rotation = 0;
      }
      this.renderAll();
    },
    /* ========== 特效 ========== */
    applyEffect(type) {
      const l = this.activeLayer;
      if (!l) return;
      this.pushHistory();
      const ctx = l.canvas.getContext('2d');
      const w = l.canvas.width, h = l.canvas.height;
      if (type === 'blur' || type === 'brighten' || type === 'darken') {
        const tmp = this.cloneCanvas(l.canvas);
        ctx.clearRect(0, 0, w, h);
        ctx.save();
        ctx.filter = type === 'blur' ? 'blur(2px)'
          : (type === 'brighten' ? 'brightness(1.15)' : 'brightness(0.85)');
        ctx.drawImage(tmp, 0, 0);
        ctx.restore();
      } else {
        const img = ctx.getImageData(0, 0, w, h);
        const d = img.data;
        if (type === 'gray') {
          for (let i = 0; i < d.length; i += 4) {
            const g = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
            d[i] = d[i + 1] = d[i + 2] = g;
          }
        } else if (type === 'invert') {
          for (let i = 0; i < d.length; i += 4) {
            d[i] = 255 - d[i];
            d[i + 1] = 255 - d[i + 1];
            d[i + 2] = 255 - d[i + 2];
          }
        } else if (type === 'sharpen') {
          this.convolveSharpen(d, w, h);
        }
        ctx.putImageData(img, 0, 0);
      }
      this.renderAll();
    },
    convolveSharpen(d, w, h) {
      const src = new Uint8ClampedArray(d);
      const k = [0, -1, 0, -1, 5, -1, 0, -1, 0];
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const i = (y * w + x) * 4;
          for (let c = 0; c < 3; c++) {
            let sum = 0, ki = 0;
            for (let dy = -1; dy <= 1; dy++) {
              for (let dx = -1; dx <= 1; dx++) {
                const xx = Math.min(w - 1, Math.max(0, x + dx));
                const yy = Math.min(h - 1, Math.max(0, y + dy));
                sum += src[(yy * w + xx) * 4 + c] * k[ki++];
              }
            }
            d[i + c] = sum;
          }
        }
      }
    },
    /* ========== 文件操作 ========== */
    openImageFile(e) {
      const file = e.target.files[0];
      if (!file) return;
      this.sourceFileName = file.name;
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
          this.pushHistory();
          // 画布尺寸贴合图片实际尺寸，除非用户主动通过「调整尺寸」修改
          this.docWidth = img.width;
          this.docHeight = img.height;
          const layer = this.makeLayer('图片 ' + (++this.layerNameSeq));
          layer.x = 0;
          layer.y = 0;
          layer.canvas.getContext('2d').drawImage(img, 0, 0);
          this.layers.push(layer);
          this.activeLayerId = layer.id;
          this.$nextTick(() => this.renderAll());
        };
        img.src = ev.target.result;
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    },
    exportImage(fmt) {
      const c = document.createElement('canvas');
      c.width = this.docWidth;
      c.height = this.docHeight;
      const ctx = c.getContext('2d');
      if (fmt === 'jpeg') {
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, c.width, c.height);
      }
      this.compositeTo(ctx);
      // 浏览器环境直接用 toBlob + <a download> 保存，无需 Electron 主进程
      const mime = 'image/' + fmt;
      const ext = fmt === 'jpeg' ? 'jpg' : fmt;
      const baseName = (this.sourceFileName || 'image').replace(/\.[^.]*$/, '');
      this.downloadCanvas(c, `${baseName}.${ext}`, mime);
    },
    downloadCanvas(canvas, fileName, mime) {
      const saveBlob = (blob) => {
        if (!blob) return;
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        // 及时释放，避免内存泄漏
        window.setTimeout(() => URL.revokeObjectURL(url), 1000);
      };
      if (typeof canvas.toBlob === 'function') {
        canvas.toBlob(saveBlob, mime, 0.92);
      } else {
        // 兼容不支持 toBlob 的老浏览器
        const a = document.createElement('a');
        a.href = canvas.toDataURL(mime, 0.92);
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
      }
    },
    /* ========== 缩放 ========== */
    zoomIn() {
      this.zoom = Math.min(8, this.zoom * 1.25);
      this.renderAll();
    },
    zoomOut() {
      this.zoom = Math.max(0.05, this.zoom / 1.25);
      this.renderAll();
    },
    zoom100() {
      this.zoom = 1;
      this.renderAll();
    },
    zoomFit() {
      const box = this.$refs.scrollBox;
      if (!box) return;
      const availW = box.clientWidth - 60;
      const availH = box.clientHeight - 60;
      if (availW <= 0 || availH <= 0) return;
      this.zoom = Math.max(0.05, Math.min(8, Math.min(availW / this.docWidth, availH / this.docHeight)));
      this.renderAll();
    },
    onCanvasWheel(e) {
      if (!e.ctrlKey && !e.metaKey) return;
      e.preventDefault();
      const box = this.$refs.scrollBox;
      const canvas = this.$refs.mainCanvas;
      if (!box || !canvas || !this.layers.length) return;
      // 缩放前：鼠标在 canvas 上的像素位置 → 对应的文档坐标（缩放锚点）
      const cRect = canvas.getBoundingClientRect();
      const relX = e.clientX - cRect.left;
      const relY = e.clientY - cRect.top;
      const docX = relX / this.zoom;
      const docY = relY / this.zoom;
      // 根据滚轮方向调整缩放（每格约10%）
      const factor = e.deltaY < 0 ? 1.1 : 1 / 1.1;
      const newZoom = Math.max(0.05, Math.min(8, this.zoom * factor));
      if (newZoom === this.zoom) return;
      this.zoom = newZoom;
      this.$nextTick(() => {
        this.renderAll();
        // 缩放后：将锚点对应的像素位置移回鼠标所在位置，实现以鼠标为中心缩放
        const cRect2 = canvas.getBoundingClientRect();
        box.scrollLeft += cRect2.left + docX * this.zoom - e.clientX;
        box.scrollTop += cRect2.top + docY * this.zoom - e.clientY;
      });
    },
    /* ========== 菜单与快捷键 ========== */
    toggleMenu(name) {
      this.openMenu = this.openMenu === name ? null : name;
    },
    hoverMenu(name) {
      if (this.openMenu !== null) this.openMenu = name;
    },
    toggleBlock(key) {
      this.blocks[key] = !this.blocks[key];
    },
    runAction(act) {
      this.openMenu = null;
      if (act.startsWith('fx-')) {
        this.applyEffect(act.slice(3));
        return;
      }
      const map = {
        newDoc: () => {
          this.sizeModal = {visible: true, width: this.docWidth, height: this.docHeight, mode: 'new'};
        },
        openImage: () => this.$refs.fileInput.click(),
        exportPNG: () => this.exportImage('png'),
        exportJPG: () => this.exportImage('jpeg'),
        undo: this.undo,
        redo: this.redo,
        clearCanvas: this.clearCanvas,
        zoomIn: this.zoomIn,
        zoomOut: this.zoomOut,
        zoom100: this.zoom100,
        zoomFit: this.zoomFit,
        resizeDoc: () => {
          this.sizeModal = {visible: true, width: this.docWidth, height: this.docHeight, mode: 'resize'};
        },
        flipH: () => this.flipDoc('h'),
        flipV: () => this.flipDoc('v'),
        rotate90: this.rotateDoc90,
        addLayer: this.addLayer,
        dupLayer: this.dupLayer,
        deleteLayer: this.deleteLayer,
        layerUp: this.layerUp,
        layerDown: this.layerDown,
        mergeDown: this.mergeDown
      };
      if (map[act]) map[act]();
    },
    onKeydown(e) {
      const tag = (e.target.tagName || '').toUpperCase();
      if (tag === 'INPUT' || tag === 'TEXTAREA') return;
      const key = (e.key || '').toLowerCase();
      if ((e.ctrlKey || e.metaKey) && key === 'z') {
        e.preventDefault();
        this.undo();
      } else if ((e.ctrlKey || e.metaKey) && key === 'y') {
        e.preventDefault();
        this.redo();
      } else if (e.key === 'Delete') {
        if (this.selection) {
          // 有套索选区时只删除选区内容
          e.preventDefault();
          this.deleteSelection();
        } else {
          const layer = this.activeLayer;
          if (!layer) return;
          this.pushHistory();
          layer.canvas.getContext('2d').clearRect(0, 0, layer.canvas.width, layer.canvas.height);
          this.renderAll();
        }
      } else if ((e.ctrlKey || e.metaKey) && key === 'c' && this.selection) {
        // Ctrl+C：拷贝套索选区
        e.preventDefault();
        this.copySelection();
      } else if ((e.ctrlKey || e.metaKey) && key === 'v' && this.clipboard) {
        // Ctrl+V：粘贴剪贴板内容到新图层
        e.preventDefault();
        this.pasteFromClipboard();
      } else if (e.key === 'Enter' && this.crop) {
        // Enter：确认裁剪
        e.preventDefault();
        this.commitCrop();
      } else if (e.key === 'Escape' && this.crop) {
        // ESC：取消裁剪
        e.preventDefault();
        this.cancelCrop();
      } else if (e.key === 'Enter' && this.floatingText) {
        // Enter：固定浮动文字到当前图层
        e.preventDefault();
        this.commitText();
      } else if (e.key === 'Escape' && this.floatingText) {
        // ESC：取消浮动文字（不绘制到图层）
        e.preventDefault();
        this.cancelText();
      } else if (e.key === 'Enter' && this.transform) {
        // Enter：确认自由变换
        e.preventDefault();
        this.commitTransform();
      } else if (e.key === 'Escape' && this.transform) {
        // ESC：取消自由变换，还原
        e.preventDefault();
        this.cancelTransform();
      } else if (e.key === 'Escape' && this.selection) {
        // ESC：取消套索选区（先写回未提交的浮动像素）
        e.preventDefault();
        if (this.dragState && this.dragState.mode === 'selMove') {
          this.commitSelectionMove();
        }
        this.clearSelection();
        this.lassoDraft = null;
        this.shapeDraft = null;
        this.renderAll();
      } else if (e.key === 'Enter' && this.selection) {
        // Enter：固定套索选区内容（写回图层并取消选区）
        e.preventDefault();
        this.commitSelectionMove();
        this.selection = null;
        this.renderAll();
      }
    },
    /* ========== 颜色工具 ========== */
    hexToRgb(hex) {
      const n = parseInt(hex.replace('#', ''), 16);
      return {r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255};
    },
    rgbToHex(r, g, b) {
      const s = ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
      return '#' + s;
    }
  }
}
